diff --git a/apps/gooseforum/app/service/datamigration/file_usage_chat_cover.go b/apps/gooseforum/app/service/datamigration/file_usage_chat_cover.go
new file mode 100644
index 000000000..9c96234a0
--- /dev/null
+++ b/apps/gooseforum/app/service/datamigration/file_usage_chat_cover.go
@@ -0,0 +1,187 @@
+package datamigration
+
+import (
+	"log/slog"
+
+	db "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/connect/dbconnect"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/chat/messages"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/filemodel/filedata"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/fileUsage"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/users"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/fileusageservice"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/permission"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/userservice"
+	"gorm.io/gorm"
+)
+
+// fileUsageChatCoverBatch 是回填每批扫描的行数：只按 id 游标分批推进，不整表加载。
+const fileUsageChatCoverBatch = 500
+
+// FileUsageChatCoverResult 汇总孤儿回收前历史私信、封面和正文附件引用的回填结果（issue #1365）。
+// 这两类内容只把 URL 存在 messages.content / users.profile_cover_url 里，没有 file_usages
+// 行；不补引用的话它们的文件既对读者不可见，又会被孤儿回收任务当成从未被引用的上传删除。
+type FileUsageChatCoverResult struct {
+	Processed  int
+	Inserted   int
+	Failed     int
+	LastFailed string
+}
+
+func BackfillFileUsagesChatCover() FileUsageChatCoverResult {
+	return BackfillFileUsagesChatCoverWithDB(db.Connect())
+}
+
+// BackfillFileUsagesChatCoverWithDB 为历史私信媒体与个人封面补登 ACTIVE 附件引用，
+// 并补齐话题图集、正文和版本记录漏登的已跟踪上传（保留原有可见性）。
+// 幂等：重复执行只补缺失的行（CreateIfAbsent）。归属口径与在线写入一致：只登记
+// 「文件存在、ready、且由消息发送者 / 封面所属用户上传（封面另允许站点管理员代传）」
+// 的对象——ACTIVE 非本人引用是永久的匿名读取授权 + 永久免回收，历史 URL 落库时没有校验，
+// 回填不能把「A 把封面指向 B 的孤儿上传」变成不可撤销的公开授权。文件库查询出错按失败计数，
+// 让版本化迁移卡住并在下次启动重试。
+func BackfillFileUsagesChatCoverWithDB(conn *gorm.DB) FileUsageChatCoverResult {
+	result := FileUsageChatCoverResult{}
+	if !conn.Migrator().HasTable((&fileUsage.Entity{}).TableName()) {
+		return result
+	}
+	backfillCoverUsages(conn, &result)
+	backfillChatMediaUsages(conn, &result)
+	backfillInlineUploadUsages(conn, &result)
+	return result
+}
+
+func backfillCoverUsages(conn *gorm.DB, result *FileUsageChatCoverResult) {
+	if !conn.Migrator().HasTable((&users.EntityComplete{}).TableName()) {
+		return
+	}
+	var cursor uint64
+	for {
+		var batch []users.EntityComplete
+		if err := conn.Model(&users.EntityComplete{}).
+			Select("id", "profile_cover_url").
+			Where("id > ? AND profile_cover_url <> ?", cursor, "").
+			Order("id ASC").Limit(fileUsageChatCoverBatch).
+			Find(&batch).Error; err != nil {
+			failFileUsageBackfill(result, "cover_scan", err)
+			return
+		}
+		for i := range batch {
+			user := &batch[i]
+			cursor = user.Id
+			result.Processed++
+			name := fileusageservice.FileNameFromURL(user.ProfileCoverUrl)
+			if name == "" || len(name) > 512 {
+				continue
+			}
+			// 封面允许本人上传，或站点管理员代管上传（机器人资料由管理员编辑）。
+			owned, err := ownedBackfillFile(name, func(ownerID uint64) bool {
+				return ownerID == user.Id || isSiteManager(ownerID)
+			})
+			if err != nil {
+				failFileUsageBackfill(result, "cover_lookup", err)
+				continue
+			}
+			if !owned {
+				continue
+			}
+			insertUsageIfAbsent(conn, result, "cover_insert", fileUsage.Entity{
+				FileName:   name,
+				TargetType: fileUsage.TargetUser,
+				TargetId:   user.Id,
+				UsageType:  fileUsage.UsageCover,
+				UserId:     user.Id,
+				Status:     fileUsage.UsageStatusActive,
+			})
+		}
+		if len(batch) < fileUsageChatCoverBatch {
+			return
+		}
+	}
+}
+
+func backfillChatMediaUsages(conn *gorm.DB, result *FileUsageChatCoverResult) {
+	if !conn.Migrator().HasTable((&messages.Entity{}).TableName()) {
+		return
+	}
+	var cursor uint64
+	for {
+		var batch []messages.Entity
+		if err := conn.Model(&messages.Entity{}).
+			Select("id", "sender_id", "content", "msg_type").
+			Where("id > ?", cursor).
+			// 预筛要与 ChatMediaFileNames 的解析范围一致：图片/语音正文、站内
+			// /file/img 链接，以及可能承载 publicUrlPrefix 直读地址的 markdown 图片。
+			Where("msg_type IN ? OR content LIKE ? OR content LIKE ?", []int8{2, 3}, "%/file/img/%", "%![%").
+			Order("id ASC").Limit(fileUsageChatCoverBatch).
+			Find(&batch).Error; err != nil {
+			failFileUsageBackfill(result, "chat_media_scan", err)
+			return
+		}
+		if len(batch) == 0 {
+			return
+		}
+		for i := range batch {
+			message := &batch[i]
+			cursor = message.Id
+			result.Processed++
+			for _, name := range fileusageservice.ChatMediaFileNames(message.Content, message.MsgType) {
+				owned, err := ownedBackfillFile(name, func(ownerID uint64) bool { return ownerID == message.SenderId })
+				if err != nil {
+					failFileUsageBackfill(result, "chat_media_lookup", err)
+					continue
+				}
+				if !owned {
+					continue
+				}
+				insertUsageIfAbsent(conn, result, "chat_media_insert", fileUsage.Entity{
+					FileName:   name,
+					TargetType: fileUsage.TargetChatMessage,
+					TargetId:   message.Id,
+					UsageType:  fileUsage.UsageChatMedia,
+					UserId:     message.SenderId,
+					Status:     fileUsage.UsageStatusActive,
+				})
+			}
+		}
+	}
+}
+
+// ownedBackfillFile 校验对象名存在、ready 且归属 allowed 允许的上传者。只读元数据，不拉
+// content BLOB；查询出错返回错误，不能把「读不到归属」当成「不属于」后静默跳过。
+func ownedBackfillFile(name string, allowed func(ownerID uint64) bool) (bool, error) {
+	file, err := filedata.GetFileMetadataByName(name)
+	if err != nil {
+		return false, err
+	}
+	if file == nil || file.StorageStatus != filedata.StorageStatusReady {
+		return false, nil
+	}
+	return allowed(file.UserId), nil
+}
+
+// isSiteManager 判断上传者当前是否持有站点管理权限（代管管理员给机器人上传封面）。
+func isSiteManager(userID uint64) bool {
+	if userID == 0 {
+		return false
+	}
+	roleID, ok := userservice.GetUserRoleId(userID)
+	return ok && permission.CheckRole(roleID, permission.SiteManager)
+}
+
+func insertUsageIfAbsent(conn *gorm.DB, result *FileUsageChatCoverResult, stage string, row fileUsage.Entity) {
+	inserted, err := fileUsage.CreateIfAbsentTx(conn, &row)
+	if err != nil {
+		result.Failed++
+		result.LastFailed = stage + ":" + err.Error()
+		slog.Error("file usage chat/cover backfill insert failed", "stage", stage, "fileName", row.FileName, "err", err)
+		return
+	}
+	if inserted > 0 {
+		result.Inserted++
+	}
+}
+
+func failFileUsageBackfill(result *FileUsageChatCoverResult, stage string, err error) {
+	result.Failed++
+	result.LastFailed = stage + ":" + err.Error()
+	slog.Error("file usage chat/cover backfill scan failed", "stage", stage, "err", err)
+}

diff --git a/apps/gooseforum/app/service/datamigration/file_usage_chat_cover_test.go b/apps/gooseforum/app/service/datamigration/file_usage_chat_cover_test.go
new file mode 100644
index 000000000..d2042b0eb
--- /dev/null
+++ b/apps/gooseforum/app/service/datamigration/file_usage_chat_cover_test.go
@@ -0,0 +1,280 @@
+package datamigration
+
+import (
+	"context"
+	"encoding/json"
+	"fmt"
+	"testing"
+	"time"
+
+	fileDB "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/connect/db4fileconnect"
+	db "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/connect/dbconnect"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/chat/messages"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/filemodel/filedata"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/fileUsage"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/pageConfig"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/rolePermissionRs"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/users"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/hotdataserve"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/fileusageservice"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/permission"
+	"gorm.io/gorm"
+)
+
+// prepareChatCoverBackfillDB 迁移模块库/文件库，并把存储配置缓存置空（公开前缀按库内配置
+// 现读，与迁移进程保持一致）。
+func prepareChatCoverBackfillDB(t *testing.T) *gorm.DB {
+	t.Helper()
+	conn := db.Connect()
+	if err := conn.AutoMigrate(&users.EntityComplete{}, &messages.Entity{}, &fileUsage.Entity{}, &pageConfig.Entity{}, &rolePermissionRs.Entity{}); err != nil {
+		t.Fatalf("migrate module tables: %v", err)
+	}
+	if err := fileDB.Connect().AutoMigrate(&filedata.Entity{}); err != nil {
+		t.Fatalf("migrate file_data: %v", err)
+	}
+	hotdataserve.ClearStorageSettingsConfigCache()
+	t.Cleanup(hotdataserve.ClearStorageSettingsConfigCache)
+	return conn
+}
+
+// seedLegacyUpload 造一个「上传后从未被引用」的历史文件：ready 行 + 归属行，创建时间回溯到
+// TTL 之外，只有内容引用能让它免于回收。
+func seedLegacyUpload(t *testing.T, ownerID uint64, name string) {
+	t.Helper()
+	if _, err := filedata.SaveFile(ownerID, name, "image/png", []byte("png")); err != nil {
+		t.Fatalf("seed file %s: %v", name, err)
+	}
+	if err := fileusageservice.AddUploadOwner(ownerID, name); err != nil {
+		t.Fatalf("add upload owner %s: %v", name, err)
+	}
+	if err := fileDB.Connect().Exec("UPDATE file_data SET created_at = ? WHERE name = ?", time.Now().Add(-8*24*time.Hour), name).Error; err != nil {
+		t.Fatalf("backdate %s: %v", name, err)
+	}
+	t.Cleanup(func() {
+		_ = filedata.DeleteByName(name)
+		db.Connect().Where("file_name = ?", name).Delete(&fileUsage.Entity{})
+	})
+}
+
+func assertActiveUsage(t *testing.T, conn *gorm.DB, fileName, targetType, usageType string, targetID, userID uint64) {
+	t.Helper()
+	var rows []fileUsage.Entity
+	if err := conn.Where("file_name = ? AND target_type = ? AND usage_type = ?", fileName, targetType, usageType).Find(&rows).Error; err != nil {
+		t.Fatalf("load usage %s: %v", fileName, err)
+	}
+	if len(rows) != 1 {
+		t.Fatalf("usage rows for %s = %d, want 1", fileName, len(rows))
+	}
+	if rows[0].Status != fileUsage.UsageStatusActive || rows[0].TargetId != targetID || rows[0].UserId != userID {
+		t.Fatalf("usage for %s = %+v, want ACTIVE target %d owner %d", fileName, rows[0], targetID, userID)
+	}
+}
+
+// TestBackfillFileUsagesChatCoverProtectsHistoricalMedia 是 issue #1365 的部署回归：
+// 历史私信图片与个人封面只存 URL，回填引用前会被孤儿回收任务直接删掉。
+func TestBackfillFileUsagesChatCoverProtectsHistoricalMedia(t *testing.T) {
+	conn := prepareChatCoverBackfillDB(t)
+	const (
+		senderID   = 9_800_500_001
+		convID     = 9_800_500_101
+		chatID     = 9_800_500_201
+		inlineID   = 9_800_500_202
+		chatName   = "2026/10/01/legacy-chat.png"
+		inlineName = "2026/10/01/legacy-inline.png"
+		coverName  = "2026/10/01/legacy-cover.png"
+	)
+	seedLegacyUpload(t, senderID, chatName)
+	seedLegacyUpload(t, senderID, inlineName)
+	seedLegacyUpload(t, senderID, coverName)
+	messagesRows := []messages.Entity{
+		{Id: chatID, ConvId: convID, SenderId: senderID, Content: "/file/img/" + chatName, MsgType: 2},
+		{Id: inlineID, ConvId: convID, SenderId: senderID, Content: "看这个 ![](/file/img/" + inlineName + ")", MsgType: 1},
+	}
+	if err := conn.Create(&messagesRows).Error; err != nil {
+		t.Fatalf("seed messages: %v", err)
+	}
+	user := users.MakeUser(fmt.Sprintf("legacy-cover-%d", senderID), "secret123", fmt.Sprintf("legacy-cover-%d@example.test", senderID))
+	user.Id = senderID
+	user.ProfileCoverUrl = "/file/img/" + coverName
+	if err := conn.Create(user).Error; err != nil {
+		t.Fatalf("seed user: %v", err)
+	}
+	t.Cleanup(func() {
+		conn.Where("id IN ?", []uint64{chatID, inlineID}).Delete(&messages.Entity{})
+		conn.Where("id = ?", senderID).Delete(&users.EntityComplete{})
+	})
+
+	for _, name := range []string{chatName, inlineName, coverName} {
+		if fileUsage.HasAnyReferences(name) {
+			t.Fatalf("seeded legacy file %s already has a content reference", name)
+		}
+	}
+
+	result := BackfillFileUsagesChatCoverWithDB(conn)
+	if result.Failed > 0 {
+		t.Fatalf("backfill failed=%d last=%s", result.Failed, result.LastFailed)
+	}
+	if result.Inserted != 3 {
+		t.Fatalf("backfill inserted=%d, want 3 (chat image, inline image, cover)", result.Inserted)
+	}
+	assertActiveUsage(t, conn, chatName, fileUsage.TargetChatMessage, fileUsage.UsageChatMedia, chatID, senderID)
+	assertActiveUsage(t, conn, inlineName, fileUsage.TargetChatMessage, fileUsage.UsageChatMedia, inlineID, senderID)
+	assertActiveUsage(t, conn, coverName, fileUsage.TargetUser, fileUsage.UsageCover, senderID, senderID)
+
+	if _, err := fileusageservice.CleanupOrphanUploads(context.Background(), time.Now().Add(-fileusageservice.OrphanUploadTTL), 200); err != nil {
+		t.Fatalf("CleanupOrphanUploads() error = %v", err)
+	}
+	for _, name := range []string{chatName, inlineName, coverName} {
+		if filedata.GetByName(name).Id == 0 {
+			t.Fatalf("historical file %s was reclaimed despite the backfilled reference", name)
+		}
+	}
+
+	// 幂等：第二次执行不再插入任何行。
+	again := BackfillFileUsagesChatCoverWithDB(conn)
+	if again.Failed > 0 || again.Inserted != 0 {
+		t.Fatalf("second run inserted=%d failed=%d, want 0/0", again.Inserted, again.Failed)
+	}
+}
+
+// TestBackfillFileUsagesChatCoverResolvesPublicUrlPrefix 覆盖 publicUrlPrefix 直读地址：
+// 历史封面存的是 CDN 绝对 URL，回填必须解析出对象名才能登记引用。
+func TestBackfillFileUsagesChatCoverResolvesPublicUrlPrefix(t *testing.T) {
+	conn := prepareChatCoverBackfillDB(t)
+	const (
+		userID    = 9_800_500_301
+		coverName = "2026/10/01/cdn-cover.png"
+		prefix    = "https://cdn.example.test/media"
+	)
+	seedLegacyUpload(t, userID, coverName)
+	storageConfig, err := json.Marshal(pageConfig.StorageSettingsStorage{Provider: "local", PublicUrlPrefix: prefix})
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := conn.Create(&pageConfig.Entity{PageType: pageConfig.StorageSettingsPage, Config: string(storageConfig)}).Error; err != nil {
+		t.Fatalf("seed storage settings: %v", err)
+	}
+	t.Cleanup(func() {
+		conn.Where("page_type = ?", pageConfig.StorageSettingsPage).Delete(&pageConfig.Entity{})
+		hotdataserve.ClearStorageSettingsConfigCache()
+	})
+	hotdataserve.ClearStorageSettingsConfigCache()
+
+	user := users.MakeUser(fmt.Sprintf("legacy-cdn-cover-%d", userID), "secret123", fmt.Sprintf("legacy-cdn-cover-%d@example.test", userID))
+	user.Id = userID
+	user.ProfileCoverUrl = prefix + "/" + coverName
+	if err := conn.Create(user).Error; err != nil {
+		t.Fatalf("seed user: %v", err)
+	}
+	t.Cleanup(func() { conn.Where("id = ?", userID).Delete(&users.EntityComplete{}) })
+
+	// 文本消息里的 markdown 图片也可以是 CDN 直读地址：预筛必须与解析范围一致，否则这类
+	// 历史图片不会被扫描、仍会被回收。
+	const (
+		messageID  = 9_800_500_401
+		inlineName = "2026/10/01/cdn-inline.png"
+	)
+	seedLegacyUpload(t, userID, inlineName)
+	if err := conn.Create(&messages.Entity{
+		Id: messageID, ConvId: 9_800_500_402, SenderId: userID, MsgType: 1,
+		Content: fmt.Sprintf("图集 ![](%s/%s)", prefix, inlineName),
+	}).Error; err != nil {
+		t.Fatalf("seed text message: %v", err)
+	}
+	t.Cleanup(func() { conn.Where("id = ?", messageID).Delete(&messages.Entity{}) })
+
+	result := BackfillFileUsagesChatCoverWithDB(conn)
+	if result.Failed > 0 {
+		t.Fatalf("backfill failed=%d last=%s", result.Failed, result.LastFailed)
+	}
+	assertActiveUsage(t, conn, coverName, fileUsage.TargetUser, fileUsage.UsageCover, userID, userID)
+	assertActiveUsage(t, conn, inlineName, fileUsage.TargetChatMessage, fileUsage.UsageChatMedia, messageID, userID)
+}
+
+// seedLegacyUser 造一个历史用户（可带封面 URL），返回其 id。
+func seedLegacyUser(t *testing.T, conn *gorm.DB, userID uint64, coverURL string) {
+	t.Helper()
+	user := users.MakeUser(fmt.Sprintf("legacy-user-%d", userID), "secret123", fmt.Sprintf("legacy-user-%d@example.test", userID))
+	user.Id = userID
+	user.ProfileCoverUrl = coverURL
+	if err := conn.Create(user).Error; err != nil {
+		t.Fatalf("seed user %d: %v", userID, err)
+	}
+	t.Cleanup(func() { conn.Where("id = ?", userID).Delete(&users.EntityComplete{}) })
+}
+
+// seedLegacyMessage 造一条历史私信（显式 id / 发送者 / 正文）。
+func seedLegacyMessage(t *testing.T, conn *gorm.DB, messageID, senderID uint64, content string, msgType int8) {
+	t.Helper()
+	if err := conn.Create(&messages.Entity{Id: messageID, ConvId: messageID, SenderId: senderID, Content: content, MsgType: msgType}).Error; err != nil {
+		t.Fatalf("seed message %d: %v", messageID, err)
+	}
+	t.Cleanup(func() { conn.Where("id = ?", messageID).Delete(&messages.Entity{}) })
+}
+
+// TestBackfillFileUsagesChatCoverSkipsForeignFiles 是 P1 回归：历史 URL 落库时没有校验，
+// 回填不能把「A 的消息/封面指向 B 的文件」变成永久的匿名读取授权 + 免回收。
+func TestBackfillFileUsagesChatCoverSkipsForeignFiles(t *testing.T) {
+	conn := prepareChatCoverBackfillDB(t)
+	const (
+		ownerID   = 9_800_600_001
+		foreignID = 9_800_600_002
+		messageID = 9_800_600_101
+	)
+	foreignChat := "2026/10/01/foreign-chat.png"
+	foreignCover := "2026/10/01/foreign-cover.png"
+	seedLegacyUpload(t, ownerID, foreignChat)
+	seedLegacyUpload(t, ownerID, foreignCover)
+	seedLegacyUser(t, conn, foreignID, "/file/img/"+foreignCover)
+	// 发送者不是上传者：消息与封面都指向别人的文件。
+	seedLegacyMessage(t, conn, messageID, foreignID, "/file/img/"+foreignChat, 2)
+
+	result := BackfillFileUsagesChatCoverWithDB(conn)
+	if result.Failed > 0 {
+		t.Fatalf("backfill failed=%d last=%s", result.Failed, result.LastFailed)
+	}
+	if result.Inserted != 0 {
+		t.Fatalf("backfill inserted=%d, want 0 for foreign files", result.Inserted)
+	}
+	for _, name := range []string{foreignChat, foreignCover} {
+		if fileUsage.HasAnyReferences(name) {
+			t.Fatalf("foreign file %s got a public reference", name)
+		}
+	}
+}
+
+// TestBackfillFileUsagesChatCoverAllowsManagerBotCover 保留代管场景：机器人封面由站点管理员
+// 上传，引用记在机器人名下，回填必须照样登记。
+func TestBackfillFileUsagesChatCoverAllowsManagerBotCover(t *testing.T) {
+	conn := prepareChatCoverBackfillDB(t)
+	const (
+		botID     = 9_800_600_201
+		managerID = 9_800_600_202
+		roleID    = 9_800_600_203
+	)
+	const coverName = "2026/10/01/manager-bot-cover.png"
+	seedLegacyUpload(t, managerID, coverName)
+	seedLegacyUser(t, conn, botID, "/file/img/"+coverName)
+
+	manager := users.MakeUser(fmt.Sprintf("manager-%d", managerID), "secret123", fmt.Sprintf("manager-%d@example.test", managerID))
+	manager.Id = managerID
+	manager.RoleId = roleID
+	if err := conn.Create(manager).Error; err != nil {
+		t.Fatalf("seed manager: %v", err)
+	}
+	t.Cleanup(func() { conn.Where("id = ?", managerID).Delete(&users.EntityComplete{}) })
+	if err := conn.Create(&rolePermissionRs.Entity{RoleId: roleID, PermissionId: permission.SiteManager.Id()}).Error; err != nil {
+		t.Fatalf("grant site manager: %v", err)
+	}
+	permission.InvalidateRole(roleID)
+	t.Cleanup(func() {
+		conn.Where("role_id = ?", roleID).Delete(&rolePermissionRs.Entity{})
+		permission.InvalidateRole(roleID)
+	})
+
+	result := BackfillFileUsagesChatCoverWithDB(conn)
+	if result.Failed > 0 {
+		t.Fatalf("backfill failed=%d last=%s", result.Failed, result.LastFailed)
+	}
+	assertActiveUsage(t, conn, coverName, fileUsage.TargetUser, fileUsage.UsageCover, botID, botID)
+}

diff --git a/apps/gooseforum/app/service/datamigration/inline_upload_backfill.go b/apps/gooseforum/app/service/datamigration/inline_upload_backfill.go
new file mode 100644
index 000000000..85aed3412
--- /dev/null
+++ b/apps/gooseforum/app/service/datamigration/inline_upload_backfill.go
@@ -0,0 +1,132 @@
+package datamigration
+
+import (
+	"errors"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/markdown2html"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/fileUsage"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/postRevisions"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/posts"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/topics"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/fileusageservice"
+	"gorm.io/gorm"
+)
+
+// Historical inline writers did not resolve publicUrlPrefix and logged reference
+// failures after saving content. Repair tracked uploads before enabling orphan GC.
+// Retained/deleted content also pins bytes, without granting public access.
+func backfillInlineUploadUsages(conn *gorm.DB, result *FileUsageChatCoverResult) {
+	hasTopics := conn.Migrator().HasTable(&topics.Entity{})
+	hasPosts := conn.Migrator().HasTable(&posts.Entity{})
+	if hasTopics {
+		var batch []topics.Entity
+		err := conn.Unscoped().FindInBatches(&batch, fileUsageChatCoverBatch, func(_ *gorm.DB, _ int) error {
+			for _, topic := range batch {
+				status := inlineBackfillStatus(topic.DeletedAt.Valid, topic.VisibilityStatus, topic.RetentionStatus, topic.Status == 1 && topic.ProcessStatus == topics.ProcessStatusNormal)
+				if status == fileUsage.UsageStatusActive && topic.FirstPostId != 0 {
+					var first posts.Entity
+					if !hasPosts {
+						status = fileUsage.UsageStatusPending
+					} else {
+						err := conn.Unscoped().First(&first, "id = ?", topic.FirstPostId).Error
+						if err != nil && !errors.Is(err, gorm.ErrRecordNotFound) {
+							return err
+						}
+						status = inlineBackfillStatus(first.Id == 0 || first.DeletedAt.Valid, first.VisibilityStatus, first.RetentionStatus, first.ProcessStatus == posts.ProcessStatusNormal)
+					}
+				}
+				backfillInlineReferences(conn, result, topic.UserId, fileUsage.TargetTopic, topic.Id, topic.ImageUrls, status)
+			}
+			return nil
+		}).Error
+		if err != nil {
+			failFileUsageBackfill(result, "topic_inline_scan", err)
+		}
+	}
+	if !hasPosts {
+		return
+	}
+	var batch []posts.Entity
+	err := conn.Unscoped().FindInBatches(&batch, fileUsageChatCoverBatch, func(_ *gorm.DB, _ int) error {
+		for _, post := range batch {
+			var topic topics.Entity
+			if hasTopics {
+				if err := conn.Unscoped().First(&topic, "id = ?", post.TopicId).Error; err != nil && !errors.Is(err, gorm.ErrRecordNotFound) {
+					return err
+				}
+			}
+			topicStatus := inlineBackfillStatus(topic.Id == 0 || topic.DeletedAt.Valid, topic.VisibilityStatus, topic.RetentionStatus, topic.Status == 1 && topic.ProcessStatus == topics.ProcessStatusNormal)
+			status := inlineBackfillStatus(post.DeletedAt.Valid, post.VisibilityStatus, post.RetentionStatus, post.ProcessStatus == posts.ProcessStatusNormal && topicStatus == fileUsage.UsageStatusActive)
+			if topicStatus == fileUsage.UsageStatusPurged {
+				status = fileUsage.UsageStatusPurged
+			}
+			backfillInlineReferences(conn, result, post.UserId, fileUsage.TargetPost, post.Id, markdown2html.ExtractImageURLs(post.Content), status)
+		}
+		return nil
+	}).Error
+	if err != nil {
+		failFileUsageBackfill(result, "post_inline_scan", err)
+	}
+	if !conn.Migrator().HasTable(&postRevisions.Entity{}) {
+		return
+	}
+	var revisions []postRevisions.Entity
+	err = conn.FindInBatches(&revisions, fileUsageChatCoverBatch, func(_ *gorm.DB, _ int) error {
+		for _, revision := range revisions {
+			var post posts.Entity
+			if err := conn.Unscoped().First(&post, "id = ?", revision.PostId).Error; err != nil {
+				if errors.Is(err, gorm.ErrRecordNotFound) {
+					continue
+				}
+				return err
+			}
+			urls := append(markdown2html.ExtractImageURLs(revision.Content), revision.ImageUrls...)
+			backfillInlineReferences(conn, result, post.UserId, fileUsage.TargetPostRevision, revision.Id, urls, fileUsage.UsageStatusPending)
+		}
+		return nil
+	}).Error
+	if err != nil {
+		failFileUsageBackfill(result, "revision_inline_scan", err)
+	}
+}
+
+func inlineBackfillStatus(deleted bool, visibility, retention string, public bool) string {
+	if deleted || (visibility != "" && visibility != posts.VisibilityActive) || retention == posts.RetentionPurged {
+		return fileUsage.UsageStatusPurged
+	}
+	if public {
+		return fileUsage.UsageStatusActive
+	}
+	return fileUsage.UsageStatusPending
+}
+
+func backfillInlineReferences(conn *gorm.DB, result *FileUsageChatCoverResult, userID uint64, target string, targetID uint64, urls []string, status string) {
+	result.Processed++
+	seen := make(map[string]bool)
+	for _, value := range urls {
+		name := fileusageservice.FileNameFromURL(value)
+		if name == "" || len(name) > 512 || seen[name] {
+			continue
+		}
+		seen[name] = true
+		var owners int64
+		if err := conn.Model(&fileUsage.Entity{}).Where("file_name = ? AND usage_type = ? AND user_id = ?", name, fileUsage.UsageUploadOwner, userID).Count(&owners).Error; err != nil {
+			failFileUsageBackfill(result, "inline_owner_lookup", err)
+			continue
+		}
+		// Untracked legacy files are not candidates for orphan GC. Do not change
+		// their visibility or grant references to another user's tracked upload.
+		if owners == 0 {
+			continue
+		}
+		owned, err := ownedBackfillFile(name, func(ownerID uint64) bool { return ownerID == userID })
+		if err != nil {
+			failFileUsageBackfill(result, "inline_file_lookup", err)
+			continue
+		}
+		if !owned {
+			continue
+		}
+		insertUsageIfAbsent(conn, result, "inline_insert", fileUsage.Entity{FileName: name, TargetType: target, TargetId: targetID, UserId: userID, UsageType: fileUsage.UsageInlineImage, Status: status})
+	}
+}

