+func TestBackfillProtectsInlineUploadsWithoutPublishingPrivateImages(t *testing.T) {
+	conn := prepareChatCoverBackfillDB(t)
+	if err := conn.AutoMigrate(&topics.Entity{}, &posts.Entity{}, &postRevisions.Entity{}); err != nil {
+		t.Fatal(err)
+	}
+	const owner = 9800500901
+	const prefix = "https://cdn.example.test/media"
+	config, err := json.Marshal(pageConfig.StorageSettingsStorage{Provider: "local", PublicUrlPrefix: prefix})
+	if err != nil {
+		t.Fatal(err)
+	}
+	setting := pageConfig.Entity{PageType: pageConfig.StorageSettingsPage, Config: string(config)}
+	if err := conn.Create(&setting).Error; err != nil {
+		t.Fatal(err)
+	}
+	hotdataserve.ClearStorageSettingsConfigCache()
+	t.Cleanup(func() { conn.Delete(&setting); hotdataserve.ClearStorageSettingsConfigCache() })
+	names := []string{"2026/10/old-cdn-gallery.webp", "2026/10/old-cdn-post.webp", "2026/10/old-cdn-revision.webp", "2026/10/old-cdn-deleted.webp", "2026/10/old-cdn-foreign.webp", "2026/10/old-cdn-deleted-gallery.webp"}
+	for i, name := range names {
+		uploader := uint64(owner)
+		if i == 4 {
+			uploader++
+		}
+		seedLegacyUpload(t, uploader, name)
+	}
+	topic := topics.Entity{Id: 9800500902, UserId: owner, Status: 1, FirstPostId: 9800500903, ImageUrls: []string{prefix + "/" + names[0]}}
+	post := posts.Entity{Id: 9800500903, UserId: owner, TopicId: topic.Id, PostNo: 1, Content: "![](" + prefix + "/" + names[1] + ") ![](" + prefix + "/" + names[4] + ")"}
+	privateTopic := topics.Entity{Id: 9800500906, UserId: owner, Status: 1, FirstPostId: 9800500904, ImageUrls: []string{prefix + "/" + names[5]}}
+	deleted := posts.Entity{Id: 9800500904, UserId: owner, TopicId: privateTopic.Id, PostNo: 1, Content: "![](" + prefix + "/" + names[3] + ")", VisibilityStatus: posts.VisibilityUserDeleted}
+	revision := postRevisions.Entity{Id: 9800500905, PostId: post.Id, Version: 1, Content: "![](" + prefix + "/" + names[2] + ")", ProcessStatus: posts.ProcessStatusPending}
+	for _, value := range []any{&topic, &privateTopic, &post, &deleted, &revision} {
+		if err := conn.Create(value).Error; err != nil {
+			t.Fatal(err)
+		}
+		t.Cleanup(func() { conn.Unscoped().Delete(value) })
+	}
+	result := BackfillFileUsagesChatCoverWithDB(conn)
+	if result.Failed != 0 {
+		t.Fatalf("backfill: %+v", result)
+	}
+	for i, name := range names {
+		var refs []fileUsage.Entity
+		if err := conn.Where("file_name = ?", name).Find(&refs).Error; err != nil {
+			t.Fatal(err)
+		}
+		var found bool
+		for _, ref := range refs {
+			if ref.UsageType != fileUsage.UsageUploadOwner {
+				found = true
+				if i < 2 && ref.Status != fileUsage.UsageStatusActive {
+					t.Fatalf("public image not restored: %+v", ref)
+				}
+				if i >= 2 && ref.Status == fileUsage.UsageStatusActive {
+					t.Fatalf("private/foreign file made public: %+v", ref)
+				}
+			}
+		}
+		if found != (i != 4) {
+			t.Errorf("reference for %s = %v", name, found)
+		}
+	}
+	for i, name := range names {
+		if i == 4 {
+			continue
+		}
+		// A main-DB claim is the authoritative prerequisite to byte deletion.
+		if claimed, err := fileUsage.ClaimOrphanUpload(name); err != nil || claimed {
+			t.Errorf("retained content was reclaimable: %s %v %v", name, claimed, err)
+		}
+	}
+	again := BackfillFileUsagesChatCoverWithDB(conn)
+	if again.Failed != 0 || again.Inserted != 0 {
+		t.Errorf("not idempotent: %+v", again)
+	}
+}

diff --git a/apps/gooseforum/app/service/datamigration/topic_excerpt.go b/apps/gooseforum/app/service/datamigration/topic_excerpt.go
new file mode 100644
index 000000000..c800057af
--- /dev/null
+++ b/apps/gooseforum/app/service/datamigration/topic_excerpt.go
@@ -0,0 +1,145 @@
+package datamigration
+
+import (
+	"errors"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/markdown2html"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/posts"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/topics"
+	"gorm.io/gorm"
+	"gorm.io/gorm/clause"
+)
+
+// BackfillEmptyTopicExcerpts repairs persisted summaries from the effective
+// public first post, never from a pending edit. It does not reorder the feed.
+func BackfillEmptyTopicExcerpts(conn *gorm.DB) error {
+	var cursor uint64
+	for {
+		var batch []topics.Entity
+		if err := conn.Model(&topics.Entity{}).Select("id").
+			Where("id > ? AND excerpt = ?", cursor, "").
+			Where(topics.PublicScopePredicate("topics")).
+			Where(topics.FirstPostVisiblePredicate("topics")).
+			Order("id ASC").Limit(200).Find(&batch).Error; err != nil {
+			return err
+		}
+		for _, row := range batch {
+			cursor = row.Id
+			if err := conn.Transaction(func(tx *gorm.DB) error {
+				var topic topics.Entity
+				err := tx.Clauses(clause.Locking{Strength: "UPDATE"}).
+					Where("id = ? AND excerpt = ?", row.Id, "").
+					Where(topics.PublicScopePredicate("topics")).First(&topic).Error
+				if errors.Is(err, gorm.ErrRecordNotFound) {
+					return nil
+				}
+				if err != nil {
+					return err
+				}
+				var post posts.Entity
+				err = tx.Clauses(clause.Locking{Strength: "UPDATE"}).
+					Where("id = ? AND topic_id = ? AND visibility_status = ? AND process_status = ?", topic.FirstPostId, topic.Id, posts.VisibilityActive, posts.ProcessStatusNormal).
+					First(&post).Error
+				if errors.Is(err, gorm.ErrRecordNotFound) {
+					return nil
+				}
+				if err != nil {
+					return err
+				}
+				excerpt := markdown2html.ExtractDescription(post.Content, 200)
+				if excerpt == "" {
+					return nil
+				}
+				return tx.Model(&topic).UpdateColumn("excerpt", excerpt).Error
+			}); err != nil {
+				return err
+			}
+		}
+		if len(batch) < 200 {
+			return nil
+		}
+	}
+}
+
+type TopicExcerptBackfillResult struct {
+	Updated    int
+	Skipped    int
+	Failed     int
+	LastFailed string
+}
+
+// BackfillTopicExcerpt 按首帖正文重算存量话题摘要（列表卡片 description）。
+// issue #1304：摘要生成曾漏掉 Markdown 转义与 HTML 实体解码，修复只影响之后
+// 写入的摘要，存量行需一次性重算。幂等：摘要未变化不写库。
+func BackfillTopicExcerpt(conn *gorm.DB) TopicExcerptBackfillResult {
+	const batchSize = 200
+	result := TopicExcerptBackfillResult{}
+	if !conn.Migrator().HasTable(&topics.Entity{}) || !conn.Migrator().HasTable(&posts.Entity{}) {
+		return result
+	}
+
+	var cursor uint64
+	for {
+		var batch []topics.Entity
+		// Unscoped：软删除行也要重算，恢复后不会带着修复前的脏摘要回归。
+		if err := conn.Unscoped().Model(&topics.Entity{}).
+			Select("id", "excerpt", "first_post_id").
+			Where("id > ?", cursor).
+			Order("id ASC").
+			Limit(batchSize).
+			Find(&batch).Error; err != nil {
+			result.Failed++
+			result.LastFailed = err.Error()
+			return result
+		}
+		if len(batch) == 0 {
+			return result
+		}
+
+		postIDs := make([]uint64, 0, len(batch))
+		for i := range batch {
+			cursor = batch[i].Id
+			if batch[i].FirstPostId != 0 {
+				postIDs = append(postIDs, batch[i].FirstPostId)
+			}
+		}
+		contents := map[uint64]string{}
+		if len(postIDs) > 0 {
+			var firstPosts []posts.Entity
+			if err := conn.Unscoped().Model(&posts.Entity{}).
+				Select("id", "content").
+				Where("id IN ?", postIDs).
+				Find(&firstPosts).Error; err != nil {
+				result.Failed++
+				result.LastFailed = err.Error()
+				continue
+			}
+			for _, post := range firstPosts {
+				contents[post.Id] = post.Content
+			}
+		}
+
+		for i := range batch {
+			item := &batch[i]
+			content, ok := contents[item.FirstPostId]
+			if !ok || content == "" {
+				result.Skipped++
+				continue
+			}
+			excerpt := markdown2html.ExtractDescription(content, 200)
+			if excerpt == item.Excerpt {
+				result.Skipped++
+				continue
+			}
+			// Unscoped：与扫描一致，软删除行同样写入（否则作用域会静默跳过）。
+			// UpdateColumn：避免扰动 topics.updated_at（首页默认排序键）。
+			if err := conn.Unscoped().Model(&topics.Entity{}).Where("id = ?", item.Id).
+				UpdateColumn("excerpt", excerpt).Error; err != nil {
+				result.Failed++
+				result.LastFailed = err.Error()
+				continue
+			}
+			result.Updated++
+		}
+	}
+}

diff --git a/apps/gooseforum/app/service/datamigration/topic_excerpt_test.go b/apps/gooseforum/app/service/datamigration/topic_excerpt_test.go
new file mode 100644
