+		t.Fatalf("backdate stale owner %s: %v", name, err)
+	}
+	t.Cleanup(func() {
+		db.Connect().Where("file_name = ?", name).Delete(&fileUsage.Entity{})
+	})
+}
+
+func orphanUsageCount(t *testing.T, fileName string) int64 {
