+		return err
+	}); !errors.Is(err, publicationservice.ErrUnavailable) {
+		t.Fatalf("replay overwrote reason: %v", err)
+	}
+	if err := conn.First(&revision, revisionID).Error; err != nil {
+		t.Fatal(err)
+	}
