+package stickerservice
+
+import (
+	"context"
+	"errors"
+	"strings"
+	"sync"
+	"time"
+
+	db "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/connect/dbconnect"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/sticker"
+	"gorm.io/gorm"
+)
+
+// MaxPackSubscriptions bounds one account's market packs, independent of the
+// 200-entry personal library.
+const MaxPackSubscriptions = 50
+
+// A queued or importing pack is re-queueable after this long without progress,
+// so a worker lost mid-import cannot pin it forever.
+const marketImportStaleAfter = 30 * time.Minute
+
+var (
+	ErrMarketPackUnavailable  = errors.New("sticker market pack unavailable")
+	ErrMarketPackNotReady     = errors.New("sticker market pack has no imported stickers")
+	ErrMarketSubscriptionFull = errors.New("sticker market subscription limit reached")
+)
+
+var marketSyncMu sync.Mutex
+
+// MarketSyncResult summarizes one catalog refresh for the administrator.
+type MarketSyncResult struct {
+	Topics  int `json:"topics"`
+	Packs   int `json:"packs"`
+	Missing int `json:"missing"`
+}
+
+// SyncMarketCatalog refreshes topic and pack metadata from the upstream index.
+// It reads every page before writing anything, so a partial or failed fetch
+// keeps the last complete snapshot. It never downloads images or publishes.
+func SyncMarketCatalog(ctx context.Context) (MarketSyncResult, error) {
+	var result MarketSyncResult
+	if !marketSyncMu.TryLock() {
+		return result, ErrMarketBusy
+	}
+	defer marketSyncMu.Unlock()
+	config, err := loadMarketConfig()
+	if err != nil {
+		return result, err
+	}
+	if !config.Enabled {
+		return result, ErrMarketDisabled
+	}
+	ctx, cancel := context.WithTimeout(ctx, 90*time.Second)
+	defer cancel()
+	upstreamTopics, err := fetchMarketTopics(ctx, config)
+	if err != nil {
+		return result, errors.Join(ErrMarketUnavailable, err)
+	}
+	topics := make([]sticker.MarketTopic, 0, len(upstreamTopics))
+	pages := 1
+	for index, topic := range upstreamTopics {
+		id := cleanUpstreamText(topic.ID, 64)
+		if id == "" {
+			continue
+		}
+		if id == "all" {
+			pages = topic.TotalPages
+			continue
+		}
+		label := cleanUpstreamText(topic.Label, 64)
+		if label == "" {
+			label = id
+		}
+		topics = append(topics, sticker.MarketTopic{Source: MarketSourceID, UpstreamID: id, Label: label, SortOrder: index})
+	}
+	pages = min(max(pages, 1), maxMarketCatalogPages)
+	now := time.Now()
+	packs := make([]sticker.MarketPack, 0, pages*48)
+	seen := map[string]bool{}
+	for page := 1; page <= pages; page++ {
+		groups, totalPages, err := fetchMarketPage(ctx, config, page)
+		if err != nil {
+			return result, errors.Join(ErrMarketUnavailable, err)
+		}
+		if page == 1 && totalPages > pages {
+			pages = min(totalPages, maxMarketCatalogPages)
+		}
+		for _, group := range groups {
+			id := group.ID
+			if !upstreamIDRe.MatchString(id) || seen[id] {
+				continue
+			}
+			seen[id] = true
+			name := cleanUpstreamText(group.Name, 128)
+			if name == "" {
+				name = id
+			}
+			iconURL, iconText := config.marketIcon(group.Icon)
+			packs = append(packs, sticker.MarketPack{
+				Source: MarketSourceID, UpstreamID: id, Name: name, Topic: cleanUpstreamText(group.Topic, 64),
+				IconURL: iconURL, IconText: iconText,
+				UpstreamCount: max(group.EmojiCount, 0), UpstreamOrder: len(packs), Archived: group.IsArchived,
+				Status: sticker.MarketStatusNew, SyncedAt: now,
+			})
+		}
+	}
+	if len(packs) == 0 {
+		return result, errors.Join(ErrMarketUnavailable, errMarketInvalidData)
+	}
+	var missing int64
+	err = db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+		if err := sticker.UpsertMarketTopicsTx(tx, topics); err != nil {
+			return err
+		}
+		if err := sticker.UpsertMarketPacksTx(tx, packs); err != nil {
+			return err
+		}
+		missing, err = sticker.MarkMissingMarketPacksTx(tx, MarketSourceID, now)
+		return err
+	})
+	if err != nil {
+		return result, err
+	}
+	return MarketSyncResult{Topics: len(topics), Packs: len(packs), Missing: int(missing)}, nil
+}
+
+// MarketTopicItem is one browsable category.
+type MarketTopicItem struct {
+	ID    string `json:"id"`
+	Label string `json:"label"`
+}
+
+// MarketPackItem is the public view of a published pack. It never exposes
+// upstream URLs; the cover is a locally stored sticker image.
+type MarketPackItem struct {
+	ID           uint64 `json:"id"`
+	Name         string `json:"name"`
+	Topic        string `json:"topic"`
+	StickerCount int    `json:"stickerCount"`
+	CoverURL     string `json:"coverUrl"`
+}
+
+// MarketCatalogPage is one page of published packs plus the categories that
+// currently contain a published pack.
+type MarketCatalogPage struct {
+	Topics   []MarketTopicItem `json:"topics"`
+	Packs    []MarketPackItem  `json:"packs"`
+	Total    int64             `json:"total"`
+	Page     int               `json:"page"`
+	PageSize int               `json:"pageSize"`
+}
+
+// MarketPackDetail lists a published pack's usable stickers in pack order.
+type MarketPackDetail struct {
+	Pack     MarketPackItem `json:"pack"`
+	Stickers []StickerItem  `json:"stickers"`
+}
+
+func normalizePage(page, pageSize, fallback int) (int, int) {
+	if page < 1 {
+		page = 1
+	}
+	if pageSize < 1 || pageSize > 100 {
+		pageSize = fallback
+	}
+	return page, pageSize
+}
+
+// coverURLs resolves pack covers; a disabled cover sticker shows no image.
+func coverURLs(packs []sticker.MarketPack) (map[uint64]string, error) {
+	ids := make([]uint64, 0, len(packs))
+	for _, pack := range packs {
+		if pack.CoverStickerID != 0 {
+			ids = append(ids, pack.CoverStickerID)
+		}
+	}
+	urls := make(map[uint64]string, len(ids))
+	if len(ids) == 0 {
+		return urls, nil
+	}
+	entities := make([]sticker.Entity, 0, len(ids))
+	if err := db.Connect().Where("id IN ? AND is_enabled = ?", ids, true).Find(&entities).Error; err != nil {
+		return urls, err
+	}
+	for _, entity := range entities {
+		urls[entity.Id] = ResolveURLFor(entity)
+	}
+	return urls, nil
+}
+
+func marketPackItems(packs []sticker.MarketPack) ([]MarketPackItem, error) {
+	covers, err := coverURLs(packs)
+	if err != nil {
+		return nil, err
+	}
+	items := make([]MarketPackItem, 0, len(packs))
+	for _, pack := range packs {
+		items = append(items, MarketPackItem{ID: pack.Id, Name: pack.Name, Topic: pack.Topic, StickerCount: pack.ItemCount, CoverURL: covers[pack.CoverStickerID]})
+	}
+	return items, nil
+}
+
+// MarketCatalog pages the packs administrators published.
+func MarketCatalog(topic, keyword string, page, pageSize int) (MarketCatalogPage, error) {
+	page, pageSize = normalizePage(page, pageSize, 24)
+	result := MarketCatalogPage{Topics: []MarketTopicItem{}, Packs: []MarketPackItem{}, Page: page, PageSize: pageSize}
+	packs, total, err := sticker.MarketPacks(sticker.MarketPackQuery{Topic: topic, Keyword: keyword, PublishedOnly: true, Page: page, PageSize: pageSize})
+	if err != nil {
+		return result, err
+	}
+	if result.Packs, err = marketPackItems(packs); err != nil {
+		return result, err
+	}
+	result.Total = total
+	var used []string
+	if err := db.Connect().Model(&sticker.MarketPack{}).Where("published = ? AND item_count > ?", true, 0).
+		Distinct().Pluck("topic", &used).Error; err != nil {
+		return result, err
+	}
+	inUse := make(map[string]bool, len(used))
+	for _, id := range used {
+		inUse[id] = true
+	}
+	topics, err := sticker.MarketTopics("")
+	if err != nil {
+		return result, err
+	}
+	for _, topic := range topics {
+		if inUse[topic.UpstreamID] {
+			// One id listed by two sources shows once.
+			delete(inUse, topic.UpstreamID)
+			result.Topics = append(result.Topics, MarketTopicItem{ID: topic.UpstreamID, Label: topic.Label})
+		}
+	}
+	return result, nil
+}
+
+// marketStickers lists a pack's enabled, approved stickers in pack order.
+func marketStickers(packID uint64) ([]StickerItem, error) {
+	items, err := sticker.MarketItems(packID)
+	if err != nil {
+		return nil, err
+	}
+	ids := make([]uint64, 0, len(items))
+	for _, item := range items {
+		if item.StickerID != 0 {
+			ids = append(ids, item.StickerID)
+		}
+	}
+	stickers := make([]StickerItem, 0, len(ids))
+	if len(ids) == 0 {
+		return stickers, nil
+	}
+	entities := make([]sticker.Entity, 0, len(ids))
+	if err := db.Connect().Where("id IN ? AND is_enabled = ? AND review_status = ?", ids, true, sticker.ReviewStatusApproved).Find(&entities).Error; err != nil {
+		return nil, err
+	}
+	byID := make(map[uint64]sticker.Entity, len(entities))
+	for _, entity := range entities {
+		byID[entity.Id] = entity
+	}
+	for _, item := range items {
+		if entity, ok := byID[item.StickerID]; ok && entity.FileName != "" {
+			stickers = append(stickers, itemFor(entity, ""))
+			delete(byID, item.StickerID)
+		}
+	}
+	return stickers, nil
+}
+
+// MarketPackStickers returns a published pack and its usable stickers.
+func MarketPackStickers(packID uint64) (MarketPackDetail, error) {
+	var detail MarketPackDetail
+	pack, err := sticker.MarketPackByID(packID)
+	if errors.Is(err, gorm.ErrRecordNotFound) || err == nil && (!pack.Published || pack.ItemCount == 0) {
+		return detail, ErrMarketPackUnavailable
+	}
+	if err != nil {
+		return detail, err
+	}
+	items, err := marketPackItems([]sticker.MarketPack{pack})
+	if err != nil {
+		return detail, err
+	}
+	detail.Pack = items[0]
+	detail.Stickers, err = marketStickers(pack.Id)
+	return detail, err
+}
+
+// MyMarketPacks lists the account's subscribed packs that are still published,
+// in subscription order. Unpublished packs stay subscribed and reappear if an
+// administrator publishes them again.
+func MyMarketPacks(ctx context.Context, userID uint64) ([]MarketPackItem, error) {
+	subscriptions, err := sticker.SubscriptionsTx(db.ConnectContext(ctx), userID)
+	if err != nil {
+		return nil, err
+	}
+	ids := make([]uint64, 0, len(subscriptions))
+	for _, subscription := range subscriptions {
+		ids = append(ids, subscription.PackID)
+	}
+	packs, err := sticker.MarketPacksByIDs(ids)
+	if err != nil {
+		return nil, err
+	}
+	byID := make(map[uint64]sticker.MarketPack, len(packs))
+	for _, pack := range packs {
+		if pack.Published && pack.ItemCount > 0 {
+			byID[pack.Id] = pack
+		}
+	}
+	ordered := make([]sticker.MarketPack, 0, len(byID))
+	for _, subscription := range subscriptions {
+		if pack, ok := byID[subscription.PackID]; ok {
+			ordered = append(ordered, pack)
+		}
+	}
+	return marketPackItems(ordered)
+}
+
+// SubscribeMarketPack adds a published pack to the account. Repeating it is
+// idempotent; the per-account library lock serializes the subscription limit
+// and fences writes that race an account closure.
+func SubscribeMarketPack(ctx context.Context, userID, packID uint64) (MarketPackItem, error) {
+	var pack sticker.MarketPack
+	if userID == 0 || packID == 0 {
+		return MarketPackItem{}, ErrInvalidLibraryInput
+	}
+	err := db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+		if err := sticker.LockLibraryTx(tx, userID); err != nil {
+			return err
+		}
+		var err error
+		pack, err = sticker.MarketPackByIDTx(tx, packID)
+		if errors.Is(err, gorm.ErrRecordNotFound) || err == nil && (!pack.Published || pack.ItemCount == 0) {
+			return ErrMarketPackUnavailable
+		}
+		if err != nil {
+			return err
+		}
+		subscriptions, err := sticker.SubscriptionsTx(tx, userID)
+		if err != nil {
+			return err
+		}
+		order := 0
+		for _, subscription := range subscriptions {
+			if subscription.PackID == packID {
+				return nil
+			}
+			order = max(order, subscription.SortOrder+1)
+		}
+		var publishedCount int64
+		if err := tx.Table("user_sticker_packs AS usp").
+			Joins("JOIN sticker_market_packs AS smp ON smp.id = usp.pack_id").
+			Where("usp.user_id = ? AND smp.published = ?", userID, true).
+			Count(&publishedCount).Error; err != nil {
+			return err
+		}
+		if publishedCount >= MaxPackSubscriptions {
+			return ErrMarketSubscriptionFull
+		}
+		return sticker.SaveSubscriptionTx(tx, &sticker.PackSubscription{UserID: userID, PackID: packID, SortOrder: order})
+	})
+	if err != nil {
+		return MarketPackItem{}, err
+	}
+	items, err := marketPackItems([]sticker.MarketPack{pack})
+	if err != nil {
+		return MarketPackItem{}, err
+	}
+	return items[0], nil
+}
+
+// UnsubscribeMarketPack removes only the account's subscription; stickers it
+// already sent keep resolving.
+func UnsubscribeMarketPack(ctx context.Context, userID, packID uint64) error {
+	if userID == 0 || packID == 0 {
+		return ErrInvalidLibraryInput
+	}
+	return db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+		if err := sticker.LockLibraryTx(tx, userID); err != nil {
+			return err
+		}
+		return sticker.RemoveSubscriptionTx(tx, userID, packID)
+	})
+}
+
+// SaveMarketPackInput publishes, hides or reorders one pack. Name, Topic and
+// TopicLabel rename or recategorize an uploaded pack and are ignored for
+// synchronized packs, whose metadata the next sync owns.
+type SaveMarketPackInput struct {
+	ID         uint64  `json:"id"`
+	Published  bool    `json:"published"`
+	SortOrder  int     `json:"sortOrder"`
+	Name       *string `json:"name"`
+	Topic      *string `json:"topic"`
+	TopicLabel string  `json:"topicLabel"`
+}
+
+// SaveMarketPack changes administrator-owned pack state. Hiding a pack removes
+// it from the market and pickers; sent stickers keep resolving.
+func SaveMarketPack(ctx context.Context, input SaveMarketPackInput) (sticker.MarketPack, error) {
+	var pack sticker.MarketPack
+	err := db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+		var err error
+		pack, err = sticker.MarketPackByIDTx(tx, input.ID)
+		if errors.Is(err, gorm.ErrRecordNotFound) {
+			return ErrMarketPackNotFound
+		}
+		if err != nil {
+			return err
+		}
+		if input.Published && pack.ItemCount == 0 {
+			return ErrMarketPackNotReady
+		}
+		if pack.Source == MarketSourceUpload {
+			if input.Name != nil {
+				if pack.Name, err = cleanMarketPackName(*input.Name); err != nil {
+					return err
+				}
+			}
+			if input.Topic != nil || input.TopicLabel != "" {
+				topic := ""
+				if input.Topic != nil {
+					topic = *input.Topic
+				}
+				if pack.Topic, err = resolveUploadTopicTx(tx, topic, input.TopicLabel); err != nil {
+					return err
+				}
+			}
+		}
+		pack.Published = input.Published
+		pack.SortOrder = input.SortOrder
+		return sticker.SaveMarketPackTx(tx, &pack)
+	})
+	return pack, err
+}
+
+// SaveMarketStickerInput withdraws, restores or renames one market sticker.
+// An empty Name keeps the current name.
+type SaveMarketStickerInput struct {
+	StickerID uint64
+	Name      string
+	IsEnabled *bool
+}
+
+// SaveMarketSticker applies an administrator's change to one market sticker.
+// A disabled sticker cannot be inserted and its sent tokens stop resolving,
+// matching a disabled official sticker. A new name replaces the generated
+// token, and the previous name keeps resolving as for official stickers.
+// It returns the sticker before and after the change.
+func SaveMarketSticker(ctx context.Context, input SaveMarketStickerInput) (before, row sticker.Entity, err error) {
+	name := strings.TrimSpace(input.Name)
+	if name != "" && !ValidateName(name) {
+		return before, row, ErrNameInvalid
+	}
+	err = db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+		var err error
+		before, err = sticker.GetByIDTx(tx, input.StickerID)
+		if errors.Is(err, gorm.ErrRecordNotFound) || err == nil && before.Pack != sticker.PackMarket {
+			return ErrNotFound
+		}
+		if err != nil {
+			return err
+		}
+		row = before
+		if input.IsEnabled != nil {
+			row.IsEnabled = *input.IsEnabled
+		}
+		if name == "" || name == row.Name {
+			if input.IsEnabled == nil {
+				return nil
+			}
+			return tx.Model(&sticker.Entity{}).Where("id = ?", row.Id).Update("is_enabled", row.IsEnabled).Error
+		}
+		if err := checkStickerNameTx(tx, row.Id, name); err != nil {
+			return err
+		}
+		previousName := row.Name
+		// The chosen name is also the label pickers show, replacing "<pack> <n>".
+		row.Name, row.DisplayName = name, ""
+		return saveRenamedStickerTx(tx, &row, previousName)
+	})
+	if err == nil {
+		InvalidateCache()
+	}
+	return before, row, err
+}
+
+// marketImportBusy reports whether a pack is already waiting for or running an import.
+func marketImportBusy(pack sticker.MarketPack) bool {
+	if pack.Status != sticker.MarketStatusQueued && pack.Status != sticker.MarketStatusImporting {
+		return false
+	}
+	return time.Since(pack.UpdatedAt) < marketImportStaleAfter
+}

diff --git a/apps/gooseforum/app/service/stickerservice/market_admin.go b/apps/gooseforum/app/service/stickerservice/market_admin.go
new file mode 100644
index 000000000..405ff6535
--- /dev/null
+++ b/apps/gooseforum/app/service/stickerservice/market_admin.go
@@ -0,0 +1,182 @@
+package stickerservice
+
+import (
+	"errors"
+	"time"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/sticker"
+	"gorm.io/gorm"
+)
+
+// AdminMarketPack is the administrator view of one catalog pack, including
+// upstream metadata and local import state. Upstream URLs are never returned:
+// IconURL is a local thumbnail or the endpoint that creates it.
+type AdminMarketPack struct {
+	ID uint64 `json:"id"`
+	// Source is MarketSourceID for synchronized packs or MarketSourceUpload.
+	Source        string     `json:"source"`
+	UpstreamID    string     `json:"upstreamId"`
+	Name          string     `json:"name"`
+	Topic         string     `json:"topic"`
+	UpstreamCount int        `json:"upstreamCount"`
+	Archived      bool       `json:"archived"`
+	Missing       bool       `json:"missing"`
+	Status        string     `json:"status"`
+	Published     bool       `json:"published"`
+	SortOrder     int        `json:"sortOrder"`
+	ItemCount     int        `json:"itemCount"`
+	FailedCount   int        `json:"failedCount"`
+	ImportTotal   int        `json:"importTotal"`
+	LastError     string     `json:"lastError"`
+	CoverURL      string     `json:"coverUrl"`
+	IconURL       string     `json:"iconUrl"`
+	IconText      string     `json:"iconText"`
+	SyncedAt      time.Time  `json:"syncedAt"`
+	ImportedAt    *time.Time `json:"importedAt"`
+}
+
+// AdminMarketCatalogPage is one page of the full catalog for administrators.
+type AdminMarketCatalogPage struct {
+	Enabled      bool              `json:"enabled"`
+	Source       string            `json:"source"`
+	LastSyncedAt *time.Time        `json:"lastSyncedAt"`
+	Topics       []MarketTopicItem `json:"topics"`
+	Packs        []AdminMarketPack `json:"packs"`
+	Total        int64             `json:"total"`
+	Page         int               `json:"page"`
+	PageSize     int               `json:"pageSize"`
+}
+
+// AdminMarketItem is one upstream item and the local sticker holding it.
+type AdminMarketItem struct {
+	UpstreamID string `json:"upstreamId"`
+	StickerID  uint64 `json:"stickerId"`
+	Name       string `json:"name"`
+	// Aliases are previous names that sent content still resolves (issue #1428).
+	Aliases   []string `json:"aliases"`
+	URL       string   `json:"url"`
+	IsEnabled bool     `json:"isEnabled"`
+	Error     string   `json:"error"`
+}
+
+// AdminMarketPackDetail lists every item an import recorded for a pack.
+type AdminMarketPackDetail struct {
+	Pack  AdminMarketPack   `json:"pack"`
+	Items []AdminMarketItem `json:"items"`
+}
+
+func adminMarketPacks(packs []sticker.MarketPack) ([]AdminMarketPack, error) {
+	covers, err := coverURLs(packs)
+	if err != nil {
+		return nil, err
+	}
+	items := make([]AdminMarketPack, 0, len(packs))
+	for _, pack := range packs {
+		items = append(items, AdminMarketPack{
+			ID: pack.Id, Source: pack.Source, UpstreamID: pack.UpstreamID, Name: pack.Name, Topic: pack.Topic,
+			UpstreamCount: pack.UpstreamCount, Archived: pack.Archived, Missing: pack.Missing,
+			Status: pack.Status, Published: pack.Published, SortOrder: pack.SortOrder,
+			ItemCount: pack.ItemCount, FailedCount: pack.FailedCount, ImportTotal: pack.ImportTotal, LastError: pack.LastError,
+			CoverURL: covers[pack.CoverStickerID], IconURL: marketPackIconURL(pack), IconText: pack.IconText, SyncedAt: pack.SyncedAt, ImportedAt: pack.ImportedAt,
+		})
+	}
+	return items, nil
+}
+
+// AdminMarketCatalog pages the synchronized and uploaded catalog with local
+// state. status filters by "imported", "published" or one import state;
+// source by MarketSourceID or MarketSourceUpload.
+func AdminMarketCatalog(source, topic, keyword, status string, page, pageSize int) (AdminMarketCatalogPage, error) {
+	page, pageSize = normalizePage(page, pageSize, 50)
+	config, configErr := loadMarketConfig()
+	result := AdminMarketCatalogPage{Enabled: configErr == nil && config.Enabled, Source: MarketSourceID, Topics: []MarketTopicItem{}, Packs: []AdminMarketPack{}, Page: page, PageSize: pageSize}
+	if synced, err := sticker.LastMarketSync(MarketSourceID); err != nil {
+		return result, err
+	} else if !synced.IsZero() {
+		result.LastSyncedAt = &synced
+	}
+	topics, err := sticker.MarketTopics("")
+	if err != nil {
+		return result, err
+	}
+	listed := map[string]bool{}
+	for _, topic := range topics {
+		if !listed[topic.UpstreamID] {
+			listed[topic.UpstreamID] = true
+			result.Topics = append(result.Topics, MarketTopicItem{ID: topic.UpstreamID, Label: topic.Label})
+		}
+	}
+	if source != MarketSourceID && source != MarketSourceUpload {
+		source = ""
+	}
+	packs, total, err := sticker.MarketPacks(sticker.MarketPackQuery{Source: source, Topic: topic, Keyword: keyword, Status: status, Page: page, PageSize: pageSize})
+	if err != nil {
+		return result, err
+	}
+	result.Total = total
+	result.Packs, err = adminMarketPacks(packs)
+	return result, err
+}
+
+// AdminMarketPackByID returns one pack's administrator view.
+func AdminMarketPackByID(packID uint64) (AdminMarketPack, error) {
+	pack, err := sticker.MarketPackByID(packID)
+	if errors.Is(err, gorm.ErrRecordNotFound) {
+		return AdminMarketPack{}, ErrMarketPackNotFound
+	}
+	if err != nil {
+		return AdminMarketPack{}, err
+	}
+	items, err := adminMarketPacks([]sticker.MarketPack{pack})
+	if err != nil {
+		return AdminMarketPack{}, err
+	}
+	return items[0], nil
+}
+
+// AdminMarketPackItems shows every imported and failed item of a pack,
+// including disabled stickers, so administrators can review before publishing.
+func AdminMarketPackItems(packID uint64) (AdminMarketPackDetail, error) {
+	var detail AdminMarketPackDetail
+	pack, err := AdminMarketPackByID(packID)
+	if err != nil {
+		return detail, err
+	}
+	detail.Pack = pack
+	rows, err := sticker.MarketItems(packID)
+	if err != nil {
+		return detail, err
+	}
+	ids := make([]uint64, 0, len(rows))
+	for _, row := range rows {
+		if row.StickerID != 0 {
+			ids = append(ids, row.StickerID)
+		}
+	}
+	byID := map[uint64]sticker.Entity{}
+	if len(ids) > 0 {
+		entities := make([]sticker.Entity, 0, len(ids))
+		if err := sticker.FindByIDs(ids, &entities); err != nil {
+			return detail, err
+		}
+		for _, entity := range entities {
+			byID[entity.Id] = entity
+		}
+	}
+	aliases, err := sticker.AliasNamesBySticker(ids)
+	if err != nil {
+		return detail, err
+	}
+	detail.Items = make([]AdminMarketItem, 0, len(rows))
+	for _, row := range rows {
+		item := AdminMarketItem{UpstreamID: row.UpstreamID, StickerID: row.StickerID, Aliases: []string{}, Error: row.Error}
+		if names := aliases[row.StickerID]; len(names) > 0 {
+			item.Aliases = names
+		}
+		if entity, ok := byID[row.StickerID]; ok {
+			item.Name, item.URL, item.IsEnabled = entity.Name, ResolveURLFor(entity), entity.IsEnabled
+		}
+		detail.Items = append(detail.Items, item)
+	}
+	return detail, nil
+}

diff --git a/apps/gooseforum/app/service/stickerservice/market_avif.go b/apps/gooseforum/app/service/stickerservice/market_avif.go
new file mode 100644
index 000000000..13b7b4c88
--- /dev/null
+++ b/apps/gooseforum/app/service/stickerservice/market_avif.go
@@ -0,0 +1,409 @@
+package stickerservice
+
+import (
+	"bytes"
+	"encoding/binary"
+	"errors"
+	"fmt"
+	"image"
+	"image/color"
+	"image/draw"
+	"image/gif"
+	"image/png"
+	"math"
+	"sort"
+	"sync"
+
+	"github.com/gen2brain/avif"
+	xdraw "golang.org/x/image/draw"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/filemodel/filedata"
+)
+
+// Market packs often ship AVIF, which neither the upload policy nor Flutter
+// accepts. The import transcodes it once: stills become PNG (full alpha),
+// animations become GIF, the format the market already serves for animated
+// packs. The decoder is libavif/dav1d compiled to WASM; release builds use
+// the nodynamic tag so it never loads a system libavif.
+const (
+	// maxMarketAVIFFrames and marketAVIFPixelBudget bound decoded memory before
+	// any frame is decoded: 512x512 x 120 frames is about 126 MB as NRGBA.
+	maxMarketAVIFFrames   = 240
+	marketAVIFPixelBudget = 512 * 512 * 120
+	// marketGIFTarget is the preferred size of a transcoded animation; larger
+	// results retry at the next smaller side, up to the storage limit.
+	marketGIFTarget = 2 << 20
+)
+
+// marketGIFSides are the long-side caps tried in order for animations.
+var marketGIFSides = []int{512, 384, 256}
+
+// One transcode at a time keeps the decoded frames of a single sticker as the
+// memory peak; other items keep downloading meanwhile.
+var marketTranscodeMu sync.Mutex
+
+// avifBrand reports whether data starts with an AVIF ftyp box. Image sequences
+// carry the avis brand.
+func avifBrand(data []byte) (sequence, ok bool) {
+	if len(data) < 16 || string(data[4:8]) != "ftyp" {
+		return false, false
+	}
+	size := int(binary.BigEndian.Uint32(data))
+	if size < 16 || size > len(data) {
+		return false, false
+	}
+	brands := [][]byte{data[8:12]}
+	for offset := 16; offset+4 <= size; offset += 4 {
+		brands = append(brands, data[offset:offset+4])
+	}
+	for _, brand := range brands {
+		switch string(brand) {
+		case "avis":
+			sequence, ok = true, true
+		case "avif":
+			ok = true
+		}
+	}
+	return sequence, ok
+}
+
+// avifFrameCount returns the largest sample count of any track (color and
+// alpha tracks match), or 0 when the file has no movie box.
+func avifFrameCount(data []byte) (int, error) {
+	moov, found, err := isoChild(data, "moov")
+	if err != nil || !found {
+		return 0, err
+	}
+	frames := 0
+	err = isoEach(moov, "trak", func(trak []byte) error {
+		stsz, err := isoPath(trak, "mdia", "minf", "stbl", "stsz")
+		if err != nil {
+			return err
+		}
+		// FullBox header (4 bytes), sample_size (4), sample_count (4).
+		if len(stsz) < 12 {
+			return errMarketInvalidImage
+		}
+		frames = max(frames, int(binary.BigEndian.Uint32(stsz[8:12])))
+		return nil
+	})
+	if err == nil && frames == 0 {
+		err = errMarketInvalidImage
+	}
+	return frames, err
+}
+
+// isoEach calls visit with the payload of every direct child box of kind.
+func isoEach(data []byte, kind string, visit func([]byte) error) error {
+	for offset := 0; offset < len(data); {
+		if len(data)-offset < 8 {
+			return errMarketInvalidImage
+		}
+		size, header := uint64(binary.BigEndian.Uint32(data[offset:])), 8
+		switch size {
+		case 0:
+			size = uint64(len(data) - offset)
+		case 1:
+			if len(data)-offset < 16 {
+				return errMarketInvalidImage
+			}
+			size, header = binary.BigEndian.Uint64(data[offset+8:]), 16
+		}
+		if size < uint64(header) || size > uint64(len(data)-offset) {
+			return errMarketInvalidImage
+		}
+		if string(data[offset+4:offset+8]) == kind {
+			if err := visit(data[offset+header : offset+int(size)]); err != nil {
+				return err
+			}
+		}
+		offset += int(size)
+	}
+	return nil
+}
+
+var errISOFound = errors.New("found")
+
+func isoChild(data []byte, kind string) ([]byte, bool, error) {
+	var child []byte
+	err := isoEach(data, kind, func(payload []byte) error {
+		child = payload
+		return errISOFound
+	})
+	if errors.Is(err, errISOFound) {
+		return child, true, nil
+	}
+	return nil, false, err
+}
+
+func isoPath(data []byte, kinds ...string) ([]byte, error) {
+	for _, kind := range kinds {
+		child, found, err := isoChild(data, kind)
+		if err != nil {
+			return nil, err
+		}
+		if !found {
+			return nil, errMarketInvalidImage
+		}
+		data = child
+	}
+	return data, nil
+}
+
+// transcodeMarketAVIF converts AVIF bytes to PNG or GIF; callers re-detect the
+// output type. Other formats the upload policy rejects (HEIC, TIFF) stay unsupported.
+func transcodeMarketAVIF(data []byte) ([]byte, error) {
+	if _, ok := avifBrand(data); !ok {
+		return nil, errMarketUnsupportedImage
+	}
+	config, err := avif.DecodeConfig(bytes.NewReader(data))
+	if err != nil || config.Width < 1 || config.Height < 1 {
+		return nil, errMarketInvalidImage
+	}
+	if config.Width > maxMarketImageSide || config.Height > maxMarketImageSide {
+		return nil, errMarketImageTooLarge
+	}
+	frames, err := avifFrameCount(data)
+	if err != nil {
+		return nil, errMarketInvalidImage
+	}
+	frames = max(frames, 1)
+	if frames > maxMarketAVIFFrames || (frames > 1 && config.Width*config.Height*frames > marketAVIFPixelBudget) {
+		return nil, errMarketImageTooLarge
+	}
+
+	marketTranscodeMu.Lock()
+	defer marketTranscodeMu.Unlock()
+	anim, err := decodeMarketAVIF(data)
+	if err != nil {
+		return nil, errMarketInvalidImage
+	}
+	if len(anim.Image) == 0 || len(anim.Image) > frames {
+		return nil, errMarketInvalidImage
+	}
+	for i, frame := range anim.Image {
+		anim.Image[i] = toNRGBA(frame)
+	}
+	if len(anim.Image) == 1 {
+		var out bytes.Buffer
+		if err := png.Encode(&out, anim.Image[0]); err != nil {
+			return nil, errMarketInvalidImage
+		}
+		if out.Len() > filedata.MaxFileSize {
+			return nil, errMarketImageTooLarge
+		}
+		return out.Bytes(), nil
+	}
+	var best []byte
+	for _, side := range marketGIFSides {
+		if best != nil && side >= max(config.Width, config.Height) {
+			continue
+		}
+		out, err := encodeMarketGIF(anim, side)
+		if err != nil {
+			return nil, errMarketInvalidImage
+		}
+		if best == nil || len(out) < len(best) {
+			best = out
+		}
+		if len(out) <= marketGIFTarget {
+			break
+		}
+	}
+	if len(best) > filedata.MaxFileSize {
+		return nil, errMarketImageTooLarge
+	}
+	return best, nil
+}
+
+// decodeMarketAVIF turns a decoder panic on hostile input into an error.
+func decodeMarketAVIF(data []byte) (anim *avif.AVIF, err error) {
+	defer func() {
+		if recovered := recover(); recovered != nil {
+			anim, err = nil, fmt.Errorf("avif decode panic: %v", recovered)
+		}
+	}()
+	return avif.DecodeAll(bytes.NewReader(data))
+}
+
+func toNRGBA(img image.Image) *image.NRGBA {
+	bounds := img.Bounds()
+	if nrgba, ok := img.(*image.NRGBA); ok && bounds.Min == (image.Point{}) {
+		return nrgba
+	}
+	nrgba := image.NewNRGBA(image.Rect(0, 0, bounds.Dx(), bounds.Dy()))
+	draw.Draw(nrgba, nrgba.Bounds(), img, bounds.Min, draw.Src)
+	return nrgba
+}
+
+// encodeMarketGIF scales frames to fit side, quantizes them to one shared
+// palette (stable colors across frames) and merges identical neighbours.
+// GIF transparency is binary: alpha below one half becomes transparent.
+func encodeMarketGIF(anim *avif.AVIF, side int) ([]byte, error) {
+	frames := make([]*image.NRGBA, len(anim.Image))
+	for i, img := range anim.Image {
+		frames[i] = scaleToFit(img.(*image.NRGBA), side)
+	}
+	palette := marketPalette(frames)
+	nearest := paletteMatcher(palette)
+	bounds := frames[0].Bounds()
+	out := &gif.GIF{LoopCount: gifLoopCount(anim.LoopCount)}
+	elapsed, emitted := 0.0, 0
+	for i, frame := range frames {
+		if !frame.Bounds().Eq(bounds) {
+			return nil, errMarketInvalidImage
+		}
+		paletted := image.NewPaletted(bounds, palette)
+		for y := range bounds.Dy() {
+			row := frame.Pix[y*frame.Stride:]
+			for x := range bounds.Dx() {
+				if pixel := row[x*4 : x*4+4]; pixel[3] >= 128 {
+					paletted.Pix[y*paletted.Stride+x] = nearest(rgbKey(pixel))
+				}
+			}
+		}
+		delay := 0.1
+		if i < len(anim.Delay) && anim.Delay[i] > 0 {
+			delay = anim.Delay[i]
+		}
+		// Round the running total so many short frames keep the source timing.
+		elapsed += delay
+		centiseconds := max(int(math.Round(elapsed*100))-emitted, 2)
+		emitted += centiseconds
+		if last := len(out.Image) - 1; last >= 0 && bytes.Equal(out.Image[last].Pix, paletted.Pix) {
+			out.Delay[last] += centiseconds
+			continue
+		}
+		out.Image = append(out.Image, paletted)
+		out.Delay = append(out.Delay, centiseconds)
+		// Clear each frame so transparent areas never show the previous one.
+		out.Disposal = append(out.Disposal, gif.DisposalBackground)
+	}
+	var buf bytes.Buffer
+	if err := gif.EncodeAll(&buf, out); err != nil {
+		return nil, err
+	}
+	return buf.Bytes(), nil
+}
+
+// gifLoopCount maps AVIF play counts (0 = forever) to GIF repeats (0 = forever, -1 = once).
+func gifLoopCount(plays int) int {
+	switch {
+	case plays <= 0:
+		return 0
+	case plays == 1:
+		return -1
+	default:
+		return plays - 1
+	}
+}
+
+func scaleToFit(img *image.NRGBA, side int) *image.NRGBA {
+	bounds := img.Bounds()
+	long := max(bounds.Dx(), bounds.Dy())
+	if long <= side {
+		return img
+	}
+	width := max(1, bounds.Dx()*side/long)
+	height := max(1, bounds.Dy()*side/long)
+	scaled := image.NewNRGBA(image.Rect(0, 0, width, height))
+	xdraw.CatmullRom.Scale(scaled, scaled.Bounds(), img, bounds, xdraw.Src, nil)
+	return scaled
+}
+
+func rgbKey(pixel []byte) uint32 {
+	return uint32(pixel[0])<<16 | uint32(pixel[1])<<8 | uint32(pixel[2])
+}
+
+// marketPalette median-cuts a sample of opaque pixels from every frame into
+// 255 colors; index 0 is the transparent color.
+func marketPalette(frames []*image.NRGBA) color.Palette {
+	const maxSamples = 1 << 18
+	total := 0
+	for _, frame := range frames {
+		total += len(frame.Pix) / 4
+	}
+	step := max(1, total/maxSamples)
+	samples := make([]uint32, 0, min(total, maxSamples))
+	index := 0
+	for _, frame := range frames {
+		for offset := 0; offset+4 <= len(frame.Pix); offset += 4 {
+			index++
+			if index%step == 0 && frame.Pix[offset+3] >= 128 {
+				samples = append(samples, rgbKey(frame.Pix[offset:offset+4]))
+			}
+		}
+	}
+	palette := color.Palette{color.NRGBA{}}
+	if len(samples) == 0 {
+		return append(palette, color.NRGBA{A: 255})
+	}
+	boxes := [][]uint32{samples}
+	for len(boxes) < 255 {
+		widest, channel, span := -1, 0, uint32(0)
+		for i, box := range boxes {
+			if len(box) < 2 {
+				continue
+			}
+			if c, s := widestChannel(box); widest < 0 || s > span {
+				widest, channel, span = i, c, s
+			}
+		}
+		if widest < 0 || span == 0 {
+			break
+		}
+		box := boxes[widest]
+		shift := 16 - 8*channel
+		sort.Slice(box, func(i, j int) bool { return box[i]>>shift&0xff < box[j]>>shift&0xff })
+		boxes[widest] = box[:len(box)/2]
+		boxes = append(boxes, box[len(box)/2:])
+	}
+	for _, box := range boxes {
+		var r, g, b int
+		for _, c := range box {
+			r += int(c >> 16 & 0xff)
+			g += int(c >> 8 & 0xff)
+			b += int(c & 0xff)
+		}
+		n := len(box)
+		palette = append(palette, color.NRGBA{R: uint8(r / n), G: uint8(g / n), B: uint8(b / n), A: 255})
+	}
+	return palette
+}
+
+func widestChannel(box []uint32) (int, uint32) {
+	channel, span := 0, uint32(0)
+	for c := range 3 {
+		shift := 16 - 8*c
+		lo, hi := uint32(255), uint32(0)
+		for _, v := range box {
+			lo, hi = min(lo, v>>shift&0xff), max(hi, v>>shift&0xff)
+		}
+		if hi-lo > span {
+			channel, span = c, hi-lo
+		}
+	}
+	return channel, span
+}
+
+// paletteMatcher finds the closest opaque palette entry, weighting green
+// highest as the eye does, and memoizes repeated colors.
+func paletteMatcher(palette color.Palette) func(uint32) uint8 {
+	cache := make(map[uint32]uint8)
+	return func(key uint32) uint8 {
+		if index, ok := cache[key]; ok {
+			return index
+		}
+		r, g, b := int(key>>16&0xff), int(key>>8&0xff), int(key&0xff)
+		best, distance := 1, math.MaxInt
+		for i := 1; i < len(palette); i++ {
+			entry := palette[i].(color.NRGBA)
+			dr, dg, db := r-int(entry.R), g-int(entry.G), b-int(entry.B)
+			if d := 2*dr*dr + 4*dg*dg + 3*db*db; d < distance {
+				best, distance = i, d
+			}
+		}
+		cache[key] = uint8(best)
+		return uint8(best)
+	}
+}

diff --git a/apps/gooseforum/app/service/stickerservice/market_avif_test.go b/apps/gooseforum/app/service/stickerservice/market_avif_test.go
new file mode 100644
index 000000000..b76785ded
--- /dev/null
+++ b/apps/gooseforum/app/service/stickerservice/market_avif_test.go
@@ -0,0 +1,154 @@
+package stickerservice
+
+import (
+	"bytes"
+	"context"
+	"encoding/binary"
+	"errors"
+	"fmt"
+	"image"
+	"image/gif"
+	"image/png"
+	"os"
+	"strings"
+	"testing"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/sticker"
+)
+
+func readMarketFixture(t *testing.T, name string) []byte {
+	t.Helper()
+	data, err := os.ReadFile("testdata/" + name)
+	if err != nil {
+		t.Fatal(err)
+	}
+	return data
+}
+
+func TestAVIFContainerProbe(t *testing.T) {
+	animated, still := readMarketFixture(t, "market-animated.avif"), readMarketFixture(t, "market-still.avif")
+	if sequence, ok := avifBrand(animated); !ok || !sequence {
+		t.Fatalf("animated brand = (%v, %v), want an AVIF sequence", sequence, ok)
+	}
+	if sequence, ok := avifBrand(still); !ok || sequence {
+		t.Fatalf("still brand = (%v, %v), want a still AVIF", sequence, ok)
+	}
+	if _, ok := avifBrand([]byte("\x00\x00\x00\x18ftypheic\x00\x00\x00\x00mif1heic")); ok {
+		t.Fatal("HEIC must not be treated as AVIF")
+	}
+	if frames, err := avifFrameCount(animated); err != nil || frames != 3 {
+		t.Fatalf("animated frame count = %d, %v; want 3", frames, err)
+	}
+	if frames, err := avifFrameCount(still); err != nil || frames != 0 {
+		t.Fatalf("still frame count = %d, %v; want 0 without a movie box", frames, err)
+	}
+	truncated := append([]byte{}, animated[:bytes.Index(animated, []byte("moov"))+64]...)
+	if _, err := avifFrameCount(truncated); err == nil {
+		t.Fatal("a truncated movie box must be rejected")
+	}
+}
+
+// A small file may declare enormous frame counts; the budget applies before decoding.
+func TestTranscodeMarketAVIFRejectsFrameBombsBeforeDecoding(t *testing.T) {
+	data := readMarketFixture(t, "market-animated.avif")
+	for offset := 0; ; {
+		next := bytes.Index(data[offset:], []byte("stsz"))
+		if next < 0 {
+			break
+		}
+		offset += next
+		binary.BigEndian.PutUint32(data[offset+12:], 100000)
+		offset += 4
+	}
+	if _, err := transcodeMarketAVIF(data); !errors.Is(err, errMarketImageTooLarge) {
+		t.Fatalf("frame bomb error = %v, want tooLarge", err)
+	}
+}
+
+func TestTranscodeMarketAVIFAnimationToGIF(t *testing.T) {
+	out, err := transcodeMarketAVIF(readMarketFixture(t, "market-animated.avif"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	anim, err := gif.DecodeAll(bytes.NewReader(out))
+	if err != nil {
+		t.Fatal(err)
+	}
+	// Frames 2 and 3 are identical and merge; 0.05 s + 0.05 s keeps the source timing.
+	if len(anim.Image) != 2 || fmt.Sprint(anim.Delay) != "[10 10]" || anim.LoopCount != 0 {
+		t.Fatalf("gif frames=%d delays=%v loop=%d, want 2 frames [10 10] looping", len(anim.Image), anim.Delay, anim.LoopCount)
+	}
+	for i, disposal := range anim.Disposal {
+		if disposal != gif.DisposalBackground {
+			t.Fatalf("frame %d disposal = %d, want background", i, disposal)
+		}
+	}
+	first, second := anim.Image[0], anim.Image[1]
+	if _, _, _, a := first.At(0, 0).RGBA(); a != 0 {
+		t.Fatal("transparent corner became opaque")
+	}
+	if r, g, _, a := first.At(5, 8).RGBA(); a == 0 || r>>8 < 150 || g>>8 > 110 {
+		t.Fatalf("first frame square = %v, want opaque red", first.At(5, 8))
+	}
+	if r, g, _, a := second.At(10, 8).RGBA(); a == 0 || g>>8 < 140 || r>>8 > 110 {
+		t.Fatalf("second frame square = %v, want opaque green", second.At(10, 8))
+	}
+	if _, _, _, a := second.At(3, 8).RGBA(); a != 0 {
+		t.Fatal("the second frame shows the first frame's square through its transparency")
+	}
+}
+
+func TestTranscodeMarketAVIFStillToPNG(t *testing.T) {
+	out, err := transcodeMarketAVIF(readMarketFixture(t, "market-still.avif"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	img, err := png.Decode(bytes.NewReader(out))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if img.Bounds() != image.Rect(0, 0, 16, 16) {
+		t.Fatalf("png bounds = %v", img.Bounds())
+	}
+	if _, _, _, a := img.At(0, 0).RGBA(); a != 0 {
+		t.Fatal("still PNG lost its transparency")
+	}
+	if _, _, _, a := img.At(8, 8).RGBA(); a>>8 < 250 {
+		t.Fatal("still PNG square is not opaque")
+	}
+}
+
+func TestTranscodeMarketAVIFKeepsOtherFormatsUnsupported(t *testing.T) {
+	if _, err := transcodeMarketAVIF([]byte("II*\x00rest-of-a-tiff")); !errors.Is(err, errMarketUnsupportedImage) {
+		t.Fatalf("TIFF error = %v, want unsupported", err)
+	}
+}
+
+func TestMarketImportTranscodesAVIF(t *testing.T) {
+	fake := setupMarketTest(t)
+	fake.catalog(marketGroup("group-8", "AVIF Pack", 2))
+	if _, err := SyncMarketCatalog(context.Background()); err != nil {
+		t.Fatal(err)
+	}
+	fake.json[testMarketBase+"group-8.json"] = `{"id":"group-8","emojis":[
+		{"id":"moving","url":"https://cdn3.ldstatic.com/moving.avif"},
+		{"id":"still","url":"https://cdn3.ldstatic.com/still.avif"}]}`
+	fake.images["https://cdn3.ldstatic.com/moving.avif"] = readMarketFixture(t, "market-animated.avif")
+	fake.images["https://cdn3.ldstatic.com/still.avif"] = readMarketFixture(t, "market-still.avif")
+	pack := runQueuedMarketImport(t, packByUpstream(t, "group-8").Id)
+	if pack.Status != sticker.MarketStatusReady || pack.ItemCount != 2 {
+		t.Fatalf("AVIF import = %#v, want both items imported", pack)
+	}
+	items, _ := sticker.MarketItems(pack.Id)
+	extensions := map[string]string{}
+	for _, item := range items {
+		row, err := sticker.GetById(item.StickerID)
+		if err != nil {
+			t.Fatal(err)
+		}
+		extensions[item.UpstreamID] = row.FileName[strings.LastIndex(row.FileName, "."):]
+	}
+	if extensions["moving"] != ".gif" || extensions["still"] != ".png" {
+		t.Fatalf("stored extensions = %v, want GIF for the animation and PNG for the still", extensions)
+	}
+}

diff --git a/apps/gooseforum/app/service/stickerservice/market_cover.go b/apps/gooseforum/app/service/stickerservice/market_cover.go
new file mode 100644
index 000000000..894b529cd
--- /dev/null
+++ b/apps/gooseforum/app/service/stickerservice/market_cover.go
@@ -0,0 +1,190 @@
+package stickerservice
+
+import (
+	"bytes"
+	"context"
+	"errors"
+	"fmt"
+	"image"
+	"image/png"
+	"strconv"
+	"sync"
+	"time"
+
+	"github.com/gen2brain/avif"
+	"golang.org/x/sync/singleflight"
+	"gorm.io/gorm"
+
+	db "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/connect/dbconnect"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/imagepolicy"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/sticker"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/storageservice"
+)
+
+// Administrators review packs before importing them, so the admin catalog
+// needs a cover for packs the server does not hold yet. The browser never
+// loads the upstream host: the server fetches the upstream icon (or the pack's
+// first sticker when upstream lists none) through the market client, stores a
+// small still thumbnail once and serves that from local storage.
+const (
+	marketCoverSide = 160
+	// marketCoverWorkers bounds upstream fetches while a catalog page loads
+	// many covers at once.
+	marketCoverWorkers    = 4
+	marketCoverTimeout    = 30 * time.Second
+	marketCoverRetryAfter = 10 * time.Minute
+)
+
+// MarketCoverPreviewPath is the admin endpoint that materializes a cover on
+// first request; the catalog links to it until the thumbnail exists.
+const MarketCoverPreviewPath = "/api/admin/sticker-market-cover"
+
+var errMarketCoverUnavailable = errors.New("sticker market cover unavailable")
+
+var (
+	marketCoverFlights singleflight.Group
+	marketCoverSlots   = make(chan struct{}, marketCoverWorkers)
+	// marketCoverMisses remembers recent failures so a broken upstream icon is
+	// not refetched on every catalog load.
+	marketCoverMisses sync.Map
+)
+
+// marketPackIconURL is the admin cover for a pack without an imported cover.
+// Packs whose upstream cover is text still get an image of their first sticker;
+// the client falls back to the text when no image can be made.
+func marketPackIconURL(pack sticker.MarketPack) string {
+	if pack.IconFile != "" {
+		return storageservice.PublicAccessPath(pack.IconFile)
+	}
+	if pack.Source != MarketSourceID {
+		// Uploaded packs only ever show the cover of a stored sticker.
+		return ""
+	}
+	return MarketCoverPreviewPath + "?id=" + strconv.FormatUint(pack.Id, 10)
+}
+
+// MarketCoverPreview returns the stored thumbnail of a pack's upstream cover,
+// fetching and storing it on first use.
+func MarketCoverPreview(ctx context.Context, packID uint64) (string, error) {
+	pack, err := sticker.MarketPackByID(packID)
+	if errors.Is(err, gorm.ErrRecordNotFound) {
+		return "", ErrMarketPackNotFound
+	}
+	if err != nil {
+		return "", err
+	}
+	if pack.IconFile != "" {
+		return pack.IconFile, nil
+	}
+	if pack.Source != MarketSourceID {
+		return "", errMarketCoverUnavailable
+	}
+	if failed, ok := marketCoverMisses.Load(packID); ok && time.Since(failed.(time.Time)) < marketCoverRetryAfter {
+		return "", errMarketCoverUnavailable
+	}
+	name, err, _ := marketCoverFlights.Do(strconv.FormatUint(packID, 10), func() (any, error) {
+		// Waiting requests share this fetch, so it must outlive the first one.
+		fetchCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), marketCoverTimeout)
+		defer cancel()
+		select {
+		case marketCoverSlots <- struct{}{}:
+			defer func() { <-marketCoverSlots }()
+		case <-fetchCtx.Done():
+			return "", fetchCtx.Err()
+		}
+		name, err := storeMarketCover(fetchCtx, pack)
+		if err != nil {
+			marketCoverMisses.Store(packID, time.Now())
+			return "", err
+		}
+		if err := db.ConnectContext(fetchCtx).Model(&sticker.MarketPack{}).
+			Where("id = ?", packID).UpdateColumn("icon_file", name).Error; err != nil {
+			marketCoverMisses.Store(packID, time.Now())
+			return "", err
+		}
+		marketCoverMisses.Delete(packID)
+		return name, nil
+	})
+	if err != nil {
+		return "", err
+	}
+	return name.(string), nil
+}
+
+func storeMarketCover(ctx context.Context, pack sticker.MarketPack) (string, error) {
+	config, err := loadMarketConfig()
+	if err != nil {
+		return "", err
+	}
+	if !config.Enabled {
+		return "", ErrMarketDisabled
+	}
+	source := pack.IconURL
+	if source == "" {
+		emojis, err := fetchMarketGroup(ctx, config, pack.UpstreamID)
+		if err != nil {
+			return "", err
+		}
+		if len(emojis) == 0 {
+			return "", errMarketCoverUnavailable
+		}
+		source = emojis[0].URL
+	}
+	data, err := fetchMarketImageBytes(ctx, config, source)
+	if err != nil {
+		return "", err
+	}
+	thumbnail, err := marketCoverThumbnail(data)
+	if err != nil {
+		return "", err
+	}
+	return storeMarketAsset(ctx, thumbnail, "image/png")
+}
+
+// marketCoverThumbnail renders the first frame of any accepted image, AVIF
+// included, as a PNG whose long side is at most marketCoverSide.
+func marketCoverThumbnail(data []byte) ([]byte, error) {
+	var config image.Config
+	var err error
+	_, isAVIF := avifBrand(data)
+	if isAVIF {
+		config, err = avif.DecodeConfig(bytes.NewReader(data))
+	} else {
+		if _, err = imagepolicy.DetectContentType(bytes.NewReader(data)); err != nil {
+			return nil, errMarketUnsupportedImage
+		}
+		config, _, err = image.DecodeConfig(bytes.NewReader(data))
+	}
+	if err != nil || config.Width < 1 || config.Height < 1 {
+		return nil, errMarketInvalidImage
+	}
+	if config.Width > maxMarketImageSide || config.Height > maxMarketImageSide {
+		return nil, errMarketImageTooLarge
+	}
+	var frame image.Image
+	if isAVIF {
+		marketTranscodeMu.Lock()
+		frame, err = decodeMarketAVIFStill(data)
+		marketTranscodeMu.Unlock()
+	} else {
+		frame, _, err = image.Decode(bytes.NewReader(data))
+	}
+	if err != nil {
+		return nil, errMarketInvalidImage
+	}
+	var out bytes.Buffer
+	if err := png.Encode(&out, scaleToFit(toNRGBA(frame), marketCoverSide)); err != nil {
+		return nil, errMarketInvalidImage
+	}
+	return out.Bytes(), nil
+}
+
+// decodeMarketAVIFStill decodes only the first frame of a still or sequence.
+func decodeMarketAVIFStill(data []byte) (frame image.Image, err error) {
+	defer func() {
+		if recovered := recover(); recovered != nil {
+			frame, err = nil, fmt.Errorf("avif decode panic: %v", recovered)
+		}
+	}()
+	return avif.Decode(bytes.NewReader(data))
+}

diff --git a/apps/gooseforum/app/service/stickerservice/market_import.go b/apps/gooseforum/app/service/stickerservice/market_import.go
new file mode 100644
index 000000000..8fbb20a3f
--- /dev/null
+++ b/apps/gooseforum/app/service/stickerservice/market_import.go
@@ -0,0 +1,436 @@
+package stickerservice
+
+import (
+	"bytes"
+	"context"
+	"crypto/sha256"
+	"encoding/hex"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"image"
+	"log/slog"
+	"net/http"
+	"sync"
+	"time"
+
+	db "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/connect/dbconnect"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/imagepolicy"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/safefetch"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/filemodel/filedata"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/fileUsage"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/sticker"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/taskQueue"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/fileusageservice"
+	"gorm.io/gorm"
+)
+
+// TaskTypeMarketImport materializes one administrator-selected market pack.
+const TaskTypeMarketImport = "sticker-market-import"
+
+// MarketAssetPrefix holds content-addressed market images: the object name is
+// the SHA-256 of the downloaded bytes, so one image is stored once no matter
+// how many packs, URLs or sticker tokens refer to it.
+const MarketAssetPrefix = "stickers/market/"
+
+const marketImportWorkers = 4
+
+var ErrMarketPackNotFound = errors.New("sticker market pack not found")
+
+type marketImportTask struct {
+	PackID uint64 `json:"packId"`
+}
+
+// QueueMarketImport schedules a download of the pack's current upstream items.
+// Items that already have a local sticker are kept as they are; retries only
+// fetch what is missing. Publication is a separate administrator decision.
+func QueueMarketImport(ctx context.Context, packID uint64) (sticker.MarketPack, error) {
+	var pack sticker.MarketPack
+	err := db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+		var err error
+		pack, err = sticker.MarketPackByIDTx(tx, packID)
+		if errors.Is(err, gorm.ErrRecordNotFound) {
+			return ErrMarketPackNotFound
+		}
+		if err != nil {
+			return err
+		}
+		if pack.Source != MarketSourceID {
+			// Uploaded packs have no upstream to download from.
+			return ErrMarketPackNotFound
+		}
+		if marketImportBusy(pack) {
+			return ErrMarketBusy
+		}
+		payload, err := json.Marshal(marketImportTask{PackID: pack.Id})
+		if err != nil {
+			return err
+		}
+		pack.Status = sticker.MarketStatusQueued
+		pack.LastError = ""
+		if err := sticker.SaveMarketPackTx(tx, &pack); err != nil {
+			return err
+		}
+		return taskQueue.CreateTx(tx, &taskQueue.Entity{Type: TaskTypeMarketImport, Status: taskQueue.StatusPending, TaskJson: string(payload)})
+	})
+	return pack, err
+}
+
+// RunMarketImportTask downloads a pack in a background worker. A catalog or
+// network failure leaves the previously imported items untouched and returns
+// an error so the queue retries; per-item failures are recorded and reported.
+func RunMarketImportTask(ctx context.Context, task *taskQueue.Entity) error {
+	if task == nil || task.Type != TaskTypeMarketImport {
+		return errors.New("invalid sticker market import task")
+	}
+	var payload marketImportTask
+	if err := json.Unmarshal([]byte(task.TaskJson), &payload); err != nil || payload.PackID == 0 {
+		return errors.New("invalid sticker market import payload")
+	}
+	pack, err := sticker.MarketPackByID(payload.PackID)
+	if errors.Is(err, gorm.ErrRecordNotFound) {
+		return nil
+	}
+	if err != nil {
+		return err
+	}
+	if err := setMarketPackStatus(ctx, pack.Id, sticker.MarketStatusImporting, ""); err != nil {
+		return err
+	}
+	config, err := loadMarketConfig()
+	if err == nil && !config.Enabled {
+		err = ErrMarketDisabled
+	}
+	var emojis []upstreamEmoji
+	if err == nil {
+		emojis, err = fetchMarketGroup(ctx, config, pack.UpstreamID)
+	}
+	if err != nil {
+		reason := marketErrorReason(err)
+		if errors.Is(err, ErrMarketDisabled) {
+			reason = "disabled"
+		}
+		if statusErr := finishMarketImport(ctx, pack.Id, reason); statusErr != nil {
+			return errors.Join(err, statusErr)
+		}
+		return err
+	}
+	if err := startMarketImportRun(ctx, pack.Id, emojis); err != nil {
+		return err
+	}
+	importMarketItems(ctx, config, pack, emojis)
+	if err := ctx.Err(); err != nil {
+		// Lease loss or shutdown: the queue owns the retry; keep partial progress.
+		return err
+	}
+	return finishMarketImport(ctx, pack.Id, "")
+}
+
+// startMarketImportRun resets the run's progress: failed rows are retried from
+// scratch, so only stickers that already exist count before the run begins.
+func startMarketImportRun(ctx context.Context, packID uint64, emojis []upstreamEmoji) error {
+	return db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+		if err := tx.Where("pack_id = ? AND sticker_id = 0", packID).Delete(&sticker.MarketItem{}).Error; err != nil {
+			return err
+		}
+		if err := tx.Model(&sticker.MarketPack{}).Where("id = ?", packID).Update("import_total", len(emojis)).Error; err != nil {
+			return err
+		}
+		return updateMarketPackCountsTx(tx, packID)
+	})
+}
+
+// updateMarketPackCountsTx recomputes the ready/failed counters from item rows
+// so concurrent workers never lose an increment.
+func updateMarketPackCountsTx(tx *gorm.DB, packID uint64) error {
+	ready := tx.Model(&sticker.MarketItem{}).Select("count(*)").Where("pack_id = ? AND sticker_id <> 0", packID)
+	failed := tx.Model(&sticker.MarketItem{}).Select("count(*)").Where("pack_id = ? AND sticker_id = 0", packID)
+	return tx.Model(&sticker.MarketPack{}).Where("id = ?", packID).
+		Updates(map[string]any{"item_count": ready, "failed_count": failed}).Error
+}
+
+func setMarketPackStatus(ctx context.Context, packID uint64, status, reason string) error {
+	return db.ConnectContext(ctx).Model(&sticker.MarketPack{}).Where("id = ?", packID).
+		Updates(map[string]any{"status": status, "last_error": reason}).Error
+}
+
+// importMarketItems fetches every item without a local sticker using a small
+// worker pool. Already materialized items are immutable: a changed upstream
+// image never alters what earlier messages show.
+func importMarketItems(ctx context.Context, config marketConfig, pack sticker.MarketPack, emojis []upstreamEmoji) {
+	existing, err := sticker.MarketItems(pack.Id)
+	if err != nil {
+		slog.Warn("sticker market: load pack items failed", "pack", pack.Id, "err", err)
+	}
+	done := make(map[string]bool, len(existing))
+	for _, item := range existing {
+		done[item.UpstreamID] = item.StickerID != 0
+	}
+	type job struct {
+		index int
+		emoji upstreamEmoji
+	}
+	jobs := make(chan job)
+	var wg sync.WaitGroup
+	for range marketImportWorkers {
+		wg.Go(func() {
+			for next := range jobs {
+				if ctx.Err() != nil {
+					continue
+				}
+				importMarketItem(ctx, config, pack, next.index, next.emoji)
+				if err := updateMarketPackCountsTx(db.ConnectContext(ctx), pack.Id); err != nil && ctx.Err() == nil {
+					slog.Warn("sticker market: update import progress failed", "pack", pack.Id, "err", err)
+				}
+			}
+		})
+	}
+	for index, emoji := range emojis {
+		if done[emoji.ID] {
+			// Keep the upstream order current without downloading again.
+			_ = db.ConnectContext(ctx).Model(&sticker.MarketItem{}).
+				Where("pack_id = ? AND upstream_id = ?", pack.Id, emoji.ID).Update("sort_order", index).Error
+			continue
+		}
+		jobs <- job{index, emoji}
+	}
+	close(jobs)
+	wg.Wait()
+}
+
+func importMarketItem(ctx context.Context, config marketConfig, pack sticker.MarketPack, index int, emoji upstreamEmoji) {
+	item := sticker.MarketItem{PackID: pack.Id, UpstreamID: emoji.ID, SortOrder: index}
+	fileName, err := downloadMarketImage(ctx, config, emoji.URL)
+	if err == nil {
+		err = db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+			return linkMarketStickerTx(tx, &item, sticker.Entity{
+				Name:        marketStickerName(pack.Source, pack.UpstreamID, emoji.ID),
+				DisplayName: marketStickerLabel(pack.Name, index),
+				FileName:    fileName,
+				SortOrder:   index,
+				IsEnabled:   true,
+			})
+		})
+	}
+	if err == nil {
+		return
+	}
+	if ctx.Err() != nil {
+		return
+	}
+	item.StickerID = 0
+	item.Error = marketErrorReason(err)
+	if writeErr := sticker.UpsertMarketItemTx(db.ConnectContext(ctx), &item); writeErr != nil {
+		slog.Warn("sticker market: record item failure failed", "pack", pack.Id, "err", writeErr)
+	}
+}
+
+// linkMarketStickerTx records item as held by the market sticker row, creating
+// the sticker unless its stable token already exists.
+func linkMarketStickerTx(tx *gorm.DB, item *sticker.MarketItem, row sticker.Entity) error {
+	// An administrator may have renamed the sticker of an earlier attempt;
+	// its generated token is then an alias of that sticker.
+	if alias, err := sticker.AliasByNameTx(tx, row.Name); err == nil {
+		if row, err = sticker.GetByIDTx(tx, alias.StickerID); err != nil {
+			return err
+		}
+		if row.Pack != sticker.PackMarket {
+			return ErrNameExists
+		}
+		item.StickerID = row.Id
+		return sticker.UpsertMarketItemTx(tx, item)
+	} else if !errors.Is(err, gorm.ErrRecordNotFound) {
+		return err
+	}
+	inserted, err := sticker.InsertMarketStickerTx(tx, &row)
+	if err != nil {
+		return err
+	}
+	if !inserted {
+		// The token exists from an earlier, interrupted attempt; reuse it.
+		if row, err = sticker.GetByNameTx(tx, row.Name); err != nil {
+			return err
+		}
+		if row.Pack != sticker.PackMarket {
+			return ErrNameExists
+		}
+	} else if err := fileusageservice.SetStickerUsageTx(tx, row.Id, 0, row.FileName, fileUsage.UsageStatusActive); err != nil {
+		return err
+	}
+	item.StickerID = row.Id
+	return sticker.UpsertMarketItemTx(tx, item)
+}
+
+// fetchMarketImageBytes downloads one image from an allowed image host.
+func fetchMarketImageBytes(ctx context.Context, config marketConfig, rawURL string) ([]byte, error) {
+	if !config.allowedImageURL(rawURL) {
+		return nil, errMarketHostBlocked
+	}
+	result, err := marketClient.FetchImage(safefetch.WithURLPolicy(ctx, config.allowedImageURL), rawURL)
+	if err != nil {
+		return nil, err
+	}
+	if result.StatusCode != http.StatusOK {
+		return nil, errMarketStatus
+	}
+	if result.FinalURL != nil && !config.allowedImageURL(result.FinalURL.String()) {
+		return nil, errMarketHostBlocked
+	}
+	if len(result.Body) == 0 || len(result.Body) > filedata.MaxFileSize {
+		return nil, errMarketImageTooLarge
+	}
+	return result.Body, nil
+}
+
+// downloadMarketImage returns the stored object name for the image at rawURL.
+func downloadMarketImage(ctx context.Context, config marketConfig, rawURL string) (string, error) {
+	data, err := fetchMarketImageBytes(ctx, config, rawURL)
+	if err != nil {
+		return "", err
+	}
+	return storeMarketImage(ctx, data)
+}
+
+// storeMarketImage validates downloaded or uploaded bytes, transcodes AVIF,
+// and returns the content-addressed object name.
+func storeMarketImage(ctx context.Context, data []byte) (string, error) {
+	// The bytes decide the type, exactly as for member uploads (issue #1393).
+	contentType, err := imagepolicy.DetectContentType(bytes.NewReader(data))
+	if errors.Is(err, imagepolicy.ErrUnsupportedImageFormat) {
+		// AVIF is common upstream: store a PNG/GIF copy every client can render,
+		// then validate that output like any other image.
+		if data, err = transcodeMarketAVIF(data); err != nil {
+			return "", err
+		}
+		contentType, err = imagepolicy.DetectContentType(bytes.NewReader(data))
+	}
+	if errors.Is(err, imagepolicy.ErrUnsupportedImageFormat) {
+		return "", errMarketUnsupportedImage
+	}
+	if err != nil {
+		return "", errMarketInvalidImage
+	}
+	imageConfig, _, err := image.DecodeConfig(bytes.NewReader(data))
+	if err != nil {
+		return "", errMarketInvalidImage
+	}
+	if imageConfig.Width > maxMarketImageSide || imageConfig.Height > maxMarketImageSide {
+		return "", errMarketImageTooLarge
+	}
+	return storeMarketAsset(ctx, data, contentType)
+}
+
+var marketAssetLocks = struct {
+	sync.Mutex
+	held map[string]*marketAssetLock
+}{held: map[string]*marketAssetLock{}}
+
+type marketAssetLock struct {
+	sync.Mutex
+	users int
+}
+
+func lockMarketAsset(name string) func() {
+	marketAssetLocks.Lock()
+	lock := marketAssetLocks.held[name]
+	if lock == nil {
+		lock = &marketAssetLock{}
+		marketAssetLocks.held[name] = lock
+	}
+	lock.users++
+	marketAssetLocks.Unlock()
+	lock.Lock()
+	return func() {
+		lock.Unlock()
+		marketAssetLocks.Lock()
+		if lock.users--; lock.users == 0 {
+			delete(marketAssetLocks.held, name)
+		}
+		marketAssetLocks.Unlock()
+	}
+}
+
+// storeMarketAsset writes the bytes once under their content hash. The file
+// name unique index makes a concurrent writer in another process lose the
+// insert and reuse the published object instead of creating a second copy.
+func storeMarketAsset(ctx context.Context, data []byte, contentType string) (string, error) {
+	ext, ok := imagepolicy.ExtForContentType(contentType)
+	if !ok {
+		return "", errMarketUnsupportedImage
+	}
+	sum := sha256.Sum256(data)
+	name := MarketAssetPrefix + hex.EncodeToString(sum[:]) + ext
+	unlock := lockMarketAsset(name)
+	defer unlock()
+	if _, err := filedata.GetFileMetadataByNameContext(ctx, name); err == nil {
+		return name, nil
+	}
+	if _, err := filedata.SaveFile(0, name, contentType, data); err != nil {
+		if _, existing := filedata.GetFileMetadataByNameContext(ctx, name); existing == nil {
+			return name, nil
+		}
+		return "", fmt.Errorf("%w: %w", errMarketStore, err)
+	}
+	return name, nil
+}
+
+// marketStickerName is a stable token per upstream item. It is derived, not
+// copied: upstream names contain characters the token grammar rejects.
+func marketStickerName(source, packID, itemID string) string {
+	sum := sha256.Sum256([]byte(source + "\n" + packID + "\n" + itemID))
+	return "m_" + hex.EncodeToString(sum[:])[:40]
+}
+
+func marketStickerLabel(packName string, index int) string {
+	return cleanUpstreamText(fmt.Sprintf("%s %d", packName, index+1), sticker.MaxNameLen)
+}
+
+// finishMarketImport recomputes the pack summary from its item rows.
+func finishMarketImport(ctx context.Context, packID uint64, reason string) error {
+	items, err := sticker.MarketItems(packID)
+	if err != nil {
+		return err
+	}
+	ready, failed := 0, 0
+	var cover uint64
+	failedReasons := map[string]int{}
+	for _, item := range items {
+		if item.StickerID == 0 {
+			failed++
+			failedReasons[item.Error]++
+			continue
+		}
+		if cover == 0 {
+			cover = item.StickerID
+		}
+		ready++
+	}
+	status := sticker.MarketStatusReady
+	switch {
+	case reason != "" || ready == 0:
+		status = sticker.MarketStatusFailed
+	case failed > 0:
+		status = sticker.MarketStatusPartial
+	}
+	if reason == "" && ready == 0 {
+		reason = "empty"
+		// One shared cause (for example an AVIF-only pack) is more useful than
+		// "nothing imported"; mixed causes stay in the per-item list.
+		if len(failedReasons) == 1 {
+			for only := range failedReasons {
+				if only != "" {
+					reason = only
+				}
+			}
+		}
+	}
+	updates := map[string]any{"status": status, "last_error": reason, "item_count": ready, "failed_count": failed, "cover_sticker_id": cover}
+	if status != sticker.MarketStatusFailed {
+		updates["imported_at"] = time.Now()
+	}
+	err = db.ConnectContext(ctx).Model(&sticker.MarketPack{}).Where("id = ?", packID).Updates(updates).Error
+	if err == nil {
+		InvalidateCache()
+	}
+	return err
+}

