+	}
+	if _, err := SubscribeMarketPack(ctx, 42, pack.Id); err != nil {
+		t.Fatalf("members subscribe to uploaded packs like synced ones: %v", err)
+	}
+}
+
+func TestUploadedMarketAVIFFilenames(t *testing.T) {
+	setupMarketTest(t)
+	for _, archive := range []bool{false, true} {
+		pack, err := CreateMarketPack(t.Context(), CreateMarketPackInput{Name: "AVIF"})
+		if err != nil {
+			t.Fatal(err)
+		}
+		data := readMarketFixture(t, "market-still.avif")
+		name := "still.avif"
+		if archive {
+			var buffer bytes.Buffer
+			writer := zip.NewWriter(&buffer)
+			entry, _ := writer.Create("nested/still.avif")
+			_, _ = entry.Write(data)
+			_ = writer.Close()
+			data, name = buffer.Bytes(), "pack.zip"
+		}
+		result, err := UploadMarketPackFile(t.Context(), pack.Id, name, data)
+		if err != nil || result.Imported != 1 || len(result.Failed) != 0 {
+			t.Fatalf("archive=%v result=%+v err=%v", archive, result, err)
+		}
+	}
+}
+
+func seedUploadedPackCapacity(t *testing.T, count int) sticker.MarketPack {
+	t.Helper()
+	pack, err := CreateMarketPack(t.Context(), CreateMarketPackInput{Name: "Capacity"})
+	if err != nil {
+		t.Fatal(err)
+	}
+	result, err := UploadMarketPackFile(t.Context(), pack.Id, "first.png", marketPNG(t, color.RGBA{R: 255, A: 255}))
+	if err != nil || result.Imported != 1 {
+		t.Fatalf("seed: %+v %v", result, err)
+	}
+	var first sticker.MarketItem
+	if err := db.Connect().Where("pack_id = ?", pack.Id).First(&first).Error; err != nil {
+		t.Fatal(err)
+	}
+	rows := make([]sticker.MarketItem, 0, count-1)
+	for i := 1; i < count; i++ {
+		rows = append(rows, sticker.MarketItem{PackID: pack.Id, UpstreamID: fmt.Sprintf("seed-%d", i), StickerID: first.StickerID, SortOrder: i})
+	}
+	if len(rows) > 0 {
+		if err := db.Connect().CreateInBatches(rows, 100).Error; err != nil {
+			t.Fatal(err)
+		}
+	}
+	if err := finishMarketImport(t.Context(), pack.Id, ""); err != nil {
+		t.Fatal(err)
+	}
+	return pack
+}
+
+func TestUploadedFullPackDuplicateRemainsIdempotent(t *testing.T) {
+	setupMarketTest(t)
+	pack := seedUploadedPackCapacity(t, MaxMarketPackItems)
+	result, err := UploadMarketPackFile(t.Context(), pack.Id, "retry.png", marketPNG(t, color.RGBA{R: 255, A: 255}))
+	if err != nil || result.Skipped != 1 || result.Imported != 0 || len(result.Failed) != 0 {
+		t.Fatalf("full-pack retry: %+v %v", result, err)
+	}
+}
+
+func TestUploadedItemCommitRechecksPackCapacity(t *testing.T) {
+	setupMarketTest(t)
+	pack := seedUploadedPackCapacity(t, MaxMarketPackItems-1)
+	// Two upload workers may already have observed this same count/order. The
+	// commit boundary must recheck it even when their preparation was concurrent.
+	for i := 0; i < 2; i++ {
+		_, err := addUploadedMarketItem(t.Context(), pack, fmt.Sprintf("new-%d.png", i), marketPNG(t, color.RGBA{B: uint8(100 + i), A: 255}))
+		if i == 0 && err != nil {
+			t.Fatal(err)
+		}
+		if i == 1 && !errors.Is(err, errMarketPackFull) {
+			t.Fatalf("stale capacity accepted a second item: %v", err)
+		}
+	}
+	_, count, err := sticker.NextMarketItemOrder(db.Connect(), pack.Id)
+	if err != nil || count != MaxMarketPackItems {
+		t.Fatalf("count=%d err=%v", count, err)
+	}
+}

diff --git a/apps/gooseforum/app/service/stickerservice/market_upstream.go b/apps/gooseforum/app/service/stickerservice/market_upstream.go
new file mode 100644
index 000000000..e9e476cac
--- /dev/null
+++ b/apps/gooseforum/app/service/stickerservice/market_upstream.go
@@ -0,0 +1,286 @@
+package stickerservice
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"net/http"
+	"net/url"
+	"regexp"
+	"strings"
+	"time"
+	"unicode"
+	"unicode/utf8"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/preferences"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/safefetch"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/filemodel/filedata"
+)
+
+// The sticker market reads the static FluxDO / bug-v3 market index. Only the
+// server fetches it: clients never receive an upstream URL, and every image is
+// downloaded, validated and stored locally before anyone can use it.
+const (
+	MarketSourceID        = "fluxdo"
+	defaultMarketBaseURL  = "https://s.pwsh.us.kg"
+	maxMarketCatalogPages = 50
+	maxMarketPacksPerPage = 200
+	maxMarketTopics       = 200
+	// MaxMarketPackItems bounds one pack's import; larger upstream packs keep
+	// their first items in upstream order.
+	MaxMarketPackItems = 500
+	maxMarketImageSide = 4096
+)
+
+// Image hosts used by the default market index. Administrators can replace
+// the list with sticker_market.image_hosts; nothing outside it is fetched.
+var defaultMarketImageHosts = []string{"cdn.ldstatic.com", "cdn3.ldstatic.com", "idcflare.com", "linux.do"}
+
+var (
+	ErrMarketDisabled    = errors.New("sticker market disabled")
+	ErrMarketBusy        = errors.New("sticker market busy")
+	ErrMarketUnavailable = errors.New("sticker market upstream unavailable")
+)
+
+// MarketFetcher is the safefetch subset the market uses.
+type MarketFetcher interface {
+	FetchJSON(ctx context.Context, rawURL string) (safefetch.Result, error)
+	FetchImage(ctx context.Context, rawURL string) (safefetch.Result, error)
+}
+
+// SwapMarketFetcher replaces the upstream client and returns a restore
+// function. It exists for tests, which must never reach the real market.
+func SwapMarketFetcher(fetcher MarketFetcher) func() {
+	previous := marketClient
+	marketClient = fetcher
+	return func() { marketClient = previous }
+}
+
+var marketClient MarketFetcher = safefetch.New(safefetch.Config{
+	ConnectTimeout: 5 * time.Second,
+	TotalTimeout:   20 * time.Second,
+	MaxBodyBytes:   filedata.MaxFileSize,
+	MaxConcurrency: 4,
+	// Image CDNs serve multi-megabyte GIFs; on networks whose IPv6 path
+	// connects but stalls, IPv6-first dialing turns every item into a timeout.
+	PreferIPv4: true,
+})
+
+type marketConfig struct {
+	Enabled    bool
+	BaseURL    string
+	baseHost   string
+	ImageHosts map[string]bool
+}
+
+func loadMarketConfig() (marketConfig, error) {
+	config := marketConfig{Enabled: preferences.GetBool("sticker_market.enabled", true), ImageHosts: map[string]bool{}}
+	base, err := url.Parse(strings.TrimRight(preferences.GetString("sticker_market.base_url", defaultMarketBaseURL), "/"))
+	if err != nil || base.Scheme != "https" || base.Host == "" || base.User != nil || base.RawQuery != "" || base.Fragment != "" {
+		return config, fmt.Errorf("%w: sticker_market.base_url must be an https origin", ErrMarketUnavailable)
+	}
+	config.BaseURL = base.String()
+	config.baseHost = strings.ToLower(base.Host)
+	hosts := preferences.GetStringSlice("sticker_market.image_hosts")
+	if len(hosts) == 0 {
+		hosts = defaultMarketImageHosts
+	}
+	for _, host := range hosts {
+		if host = strings.ToLower(strings.TrimSpace(host)); host != "" {
+			config.ImageHosts[host] = true
+		}
+	}
+	return config, nil
+}
+
+// allowedImageURL accepts only HTTPS URLs on an allow-listed host and the
+// default port; safefetch then rejects private or reserved addresses.
+func (c marketConfig) allowedImageURL(raw string) bool {
+	u, err := url.Parse(raw)
+	if err != nil || u.Scheme != "https" || u.User != nil || (u.Port() != "" && u.Port() != "443") {
+		return false
+	}
+	return c.ImageHosts[strings.ToLower(u.Hostname())]
+}
+
+func (c marketConfig) allowedIndexURL(raw string) bool {
+	u, err := url.Parse(raw)
+	return err == nil && u.Scheme == "https" && u.User == nil && strings.EqualFold(u.Host, c.baseHost)
+}
+
+// marketIcon splits the upstream cover into an allow-listed image URL or a
+// short text cover (some packs use one emoji or letter); anything else is dropped.
+func (c marketConfig) marketIcon(raw string) (iconURL, iconText string) {
+	raw = strings.TrimSpace(raw)
+	if strings.Contains(raw, "://") {
+		if len(raw) <= 512 && c.allowedImageURL(raw) {
+			return raw, ""
+		}
+		return "", ""
+	}
+	return "", cleanUpstreamText(raw, 16)
+}
+
+type upstreamTopic struct {
+	ID         string `json:"id"`
+	Label      string `json:"label"`
+	TotalPages int    `json:"totalPages"`
+}
+
+type upstreamGroup struct {
+	ID         string `json:"id"`
+	Name       string `json:"name"`
+	Icon       string `json:"icon"`
+	Topic      string `json:"topic"`
+	EmojiCount int    `json:"emojiCount"`
+	IsArchived bool   `json:"isArchived"`
+}
+
+type upstreamEmoji struct {
+	ID  string `json:"id"`
+	URL string `json:"url"`
+}
+
+type upstreamGroupDetail struct {
+	ID     string          `json:"id"`
+	Emojis []upstreamEmoji `json:"emojis"`
+}
+
+// Upstream identifiers become URL path segments; keep them to a safe charset.
+var upstreamIDRe = regexp.MustCompile(`^[A-Za-z0-9_-]{1,128}$`)
+
+// cleanUpstreamText trims, drops control characters and bounds display text.
+func cleanUpstreamText(raw string, limit int) string {
+	if !utf8.ValidString(raw) {
+		return ""
+	}
+	text := strings.Map(func(r rune) rune {
+		if unicode.IsControl(r) {
+			return -1
+		}
+		return r
+	}, strings.TrimSpace(raw))
+	runes := []rune(text)
+	if len(runes) > limit {
+		runes = runes[:limit]
+	}
+	return strings.TrimSpace(string(runes))
+}
+
+// marketErrorReason maps a failure to a stable reason stored for administrators.
+// It never contains upstream URLs, addresses or response bodies.
+func marketErrorReason(err error) string {
+	switch {
+	case err == nil:
+		return ""
+	case safefetch.IsClass(err, safefetch.ErrorTimeout):
+		return "timeout"
+	case safefetch.IsClass(err, safefetch.ErrorBlocked), safefetch.IsClass(err, safefetch.ErrorRedirect), errors.Is(err, errMarketHostBlocked):
+		return "blocked"
+	case safefetch.IsClass(err, safefetch.ErrorTooLarge), errors.Is(err, errMarketImageTooLarge):
+		return "tooLarge"
+	case safefetch.IsClass(err, safefetch.ErrorContentType), errors.Is(err, errMarketUnsupportedImage):
+		return "unsupported"
+	case errors.Is(err, errMarketInvalidImage), errors.Is(err, errMarketInvalidData):
+		return "invalid"
+	case errors.Is(err, errMarketStatus):
+		return "status"
+	case errors.Is(err, errMarketStore):
+		return "storage"
+	default:
+		return "unavailable"
+	}
+}
+
+var (
+	errMarketHostBlocked      = errors.New("market host not allowed")
+	errMarketStatus           = errors.New("market upstream returned a non-200 status")
+	errMarketInvalidData      = errors.New("market upstream returned invalid data")
+	errMarketInvalidImage     = errors.New("market image is not a usable image")
+	errMarketUnsupportedImage = errors.New("market image format is not supported")
+	errMarketImageTooLarge    = errors.New("market image exceeds limits")
+	errMarketStore            = errors.New("market image could not be stored")
+)
+
+func fetchMarketJSON(ctx context.Context, config marketConfig, path string, target any) error {
+	result, err := marketClient.FetchJSON(safefetch.WithURLPolicy(ctx, config.allowedIndexURL), config.BaseURL+path)
+	if err != nil {
+		return err
+	}
+	if result.StatusCode != http.StatusOK {
+		return errMarketStatus
+	}
+	// Redirects stay on the configured index host.
+	if result.FinalURL != nil && !config.allowedIndexURL(result.FinalURL.String()) {
+		return errMarketHostBlocked
+	}
+	if err := json.Unmarshal(result.Body, target); err != nil {
+		return fmt.Errorf("%w: %w", errMarketInvalidData, err)
+	}
+	return nil
+}
+
+func fetchMarketTopics(ctx context.Context, config marketConfig) ([]upstreamTopic, error) {
+	var payload struct {
+		Topics []upstreamTopic `json:"topics"`
+	}
+	if err := fetchMarketJSON(ctx, config, "/assets/market/index/topics.json", &payload); err != nil {
+		return nil, err
+	}
+	if len(payload.Topics) == 0 || len(payload.Topics) > maxMarketTopics {
+		return nil, errMarketInvalidData
+	}
+	return payload.Topics, nil
+}
+
+func fetchMarketPage(ctx context.Context, config marketConfig, page int) ([]upstreamGroup, int, error) {
+	var payload struct {
+		Groups     []upstreamGroup `json:"groups"`
+		TotalPages int             `json:"totalPages"`
+	}
+	if err := fetchMarketJSON(ctx, config, fmt.Sprintf("/assets/market/index/page-%d.json", page), &payload); err != nil {
+		return nil, 0, err
+	}
+	if len(payload.Groups) > maxMarketPacksPerPage {
+		return nil, 0, errMarketInvalidData
+	}
+	return payload.Groups, payload.TotalPages, nil
+}
+
+// marketGroupPath mirrors the upstream file layout: ids already carry the
+// "group-" prefix in the current index; older ids do not.
+func marketGroupPath(upstreamID string) (string, error) {
+	if !upstreamIDRe.MatchString(upstreamID) {
+		return "", errMarketInvalidData
+	}
+	if !strings.HasPrefix(upstreamID, "group-") {
+		upstreamID = "group-" + upstreamID
+	}
+	return "/assets/market/" + upstreamID + ".json", nil
+}
+
+func fetchMarketGroup(ctx context.Context, config marketConfig, upstreamID string) ([]upstreamEmoji, error) {
+	path, err := marketGroupPath(upstreamID)
+	if err != nil {
+		return nil, err
+	}
+	var payload upstreamGroupDetail
+	if err := fetchMarketJSON(ctx, config, path, &payload); err != nil {
+		return nil, err
+	}
+	emojis := make([]upstreamEmoji, 0, min(len(payload.Emojis), MaxMarketPackItems))
+	seen := make(map[string]bool, len(payload.Emojis))
+	for _, emoji := range payload.Emojis {
+		if len(emojis) == MaxMarketPackItems {
+			break
+		}
+		emoji.ID = strings.TrimSpace(emoji.ID)
+		if emoji.ID == "" || len(emoji.ID) > 128 || !utf8.ValidString(emoji.ID) || seen[emoji.ID] {
+			continue
+		}
+		seen[emoji.ID] = true
+		emojis = append(emojis, emoji)
+	}
+	return emojis, nil
+}

diff --git a/apps/gooseforum/app/service/stickerservice/official_packs.go b/apps/gooseforum/app/service/stickerservice/official_packs.go
new file mode 100644
index 000000000..f127e017f
--- /dev/null
+++ b/apps/gooseforum/app/service/stickerservice/official_packs.go
@@ -0,0 +1,406 @@
+package stickerservice
+
+import (
+	"context"
+	"crypto/rand"
+	"encoding/hex"
+	"errors"
+	"regexp"
+	"slices"
+	"sort"
+	"strings"
+	"unicode"
+	"unicode/utf8"
+
+	db "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/connect/dbconnect"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/localcache"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/fileUsage"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/sticker"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/fileusageservice"
+	"gorm.io/gorm"
+)
+
+// MaxBatchStickers bounds one administrator batch action.
+const MaxBatchStickers = 500
+
+const maxPackNameLen = 64
+
+var (
+	ErrPackNameRequired = errors.New("sticker pack name required")
+	ErrPackInvalid      = errors.New("invalid sticker pack")
+)
+
+// packKeyRe matches the keys stickers store in Entity.Pack. New packs get a
+// generated key, so administrators only ever edit the display name.
+var packKeyRe = regexp.MustCompile(`^[a-z0-9][a-z0-9_-]{0,63}$`)
+
+// presetPackDefaults name and order the seeded groups until an administrator
+// edits them; other keys sort after them.
+var presetPackDefaults = map[string]struct {
+	name  string
+	order int
+}{
+	sticker.PackOfficial: {"默认", 0},
+	"emojipackage":       {"EmojiPackage", 10},
+	"flowerhd":           {"花字", 20},
+	"wxmeme":             {"程序员梗", 30},
+}
+
+const customPackOrder = 1000
+
+var officialPackCache = &localcache.Cache[[]OfficialPackItem]{MaxEntries: 1}
+
+// OfficialPackItem is the public view of one official group with enabled stickers.
+type OfficialPackItem struct {
+	Key          string `json:"key"`
+	Name         string `json:"name"`
+	CoverURL     string `json:"coverUrl"`
+	StickerCount int    `json:"stickerCount"`
+}
+
+// AdminOfficialPack is one official group with all of its stickers counted.
+type AdminOfficialPack struct {
+	Key            string `json:"key"`
+	Name           string `json:"name"`
+	SortOrder      int    `json:"sortOrder"`
+	CoverStickerID uint64 `json:"coverStickerId"`
+	CoverURL       string `json:"coverUrl"`
+	StickerCount   int    `json:"stickerCount"`
+	EnabledCount   int    `json:"enabledCount"`
+}
+
+func validPackKey(key string) bool { return packKeyRe.MatchString(key) }
+
+func cleanPackName(raw string) (string, error) {
+	name := strings.TrimSpace(raw)
+	if name == "" {
+		return "", ErrPackNameRequired
+	}
+	if !utf8.ValidString(name) || utf8.RuneCountInString(name) > maxPackNameLen || strings.IndexFunc(name, unicode.IsControl) >= 0 {
+		return "", ErrPackInvalid
+	}
+	return name, nil
+}
+
+// packView merges stored metadata with the defaults for one key.
+func packView(key string, rows map[string]sticker.OfficialPack) (name string, order int, cover uint64) {
+	if row, ok := rows[key]; ok {
+		return row.Name, row.SortOrder, row.CoverStickerID
+	}
+	if preset, ok := presetPackDefaults[key]; ok {
+		return preset.name, preset.order, 0
+	}
+	return key, customPackOrder, 0
+}
+
+func officialPackRows(tx *gorm.DB) (map[string]sticker.OfficialPack, error) {
+	rows, err := sticker.OfficialPacksTx(tx)
+	if err != nil {
+		return nil, err
+	}
+	byKey := make(map[string]sticker.OfficialPack, len(rows))
+	for _, row := range rows {
+		byKey[row.Key] = row
+	}
+	return byKey, nil
+}
+
+func sortPacks[T any](packs []T, order func(T) (int, string)) {
+	sort.SliceStable(packs, func(i, j int) bool {
+		oi, ki := order(packs[i])
+		oj, kj := order(packs[j])
+		if oi != oj {
+			return oi < oj
+		}
+		return ki < kj
+	})
+}
+
+// OfficialPackList lists the official groups members can pick from, in
+// administrator order. The cover is the chosen sticker when it is still
+// enabled in the group, otherwise the group's first sticker.
+func OfficialPackList() ([]OfficialPackItem, error) {
+	return officialPackCache.GetOrLoadE("all", func() ([]OfficialPackItem, error) {
+		stickers, err := EnabledList()
+		if err != nil {
+			return nil, err
+		}
+		rows, err := officialPackRows(db.Connect())
+		if err != nil {
+			return nil, err
+		}
+		byKey := map[string]*OfficialPackItem{}
+		orders := map[string]int{}
+		var packs []*OfficialPackItem
+		for _, item := range stickers {
+			key := item.Pack
+			if key == "" {
+				key = sticker.PackOfficial
+			}
+			pack := byKey[key]
+			if pack == nil {
+				name, order, cover := packView(key, rows)
+				pack = &OfficialPackItem{Key: key, Name: name}
+				byKey[key], orders[key] = pack, order
+				packs = append(packs, pack)
+				if cover != 0 {
+					if index := slices.IndexFunc(stickers, func(s StickerItem) bool { return s.ID == cover && s.Pack == key }); index >= 0 {
+						pack.CoverURL = stickers[index].URL
+					}
+				}
+			}
+			if pack.CoverURL == "" {
+				pack.CoverURL = item.URL
+			}
+			pack.StickerCount++
+		}
+		sortPacks(packs, func(p *OfficialPackItem) (int, string) { return orders[p.Key], p.Key })
+		items := make([]OfficialPackItem, 0, len(packs))
+		for _, pack := range packs {
+			items = append(items, *pack)
+		}
+		return items, nil
+	}, stickerCacheTTL)
+}
+
+// AdminOfficialPacks lists every official group, including empty ones that
+// an administrator created, with enabled and total counts.
+func AdminOfficialPacks(ctx context.Context) ([]AdminOfficialPack, error) {
+	conn := db.ConnectContext(ctx)
+	rows, err := officialPackRows(conn)
+	if err != nil {
+		return nil, err
+	}
+	counts, err := sticker.OfficialPackCounts(conn)
+	if err != nil {
+		return nil, err
+	}
+	byKey := map[string]*AdminOfficialPack{}
+	add := func(key string) *AdminOfficialPack {
+		if pack, ok := byKey[key]; ok {
+			return pack
+		}
+		name, order, cover := packView(key, rows)
+		pack := &AdminOfficialPack{Key: key, Name: name, SortOrder: order, CoverStickerID: cover}
+		byKey[key] = pack
+		return pack
+	}
+	add(sticker.PackOfficial)
+	for key := range rows {
+		add(key)
+	}
+	for _, count := range counts {
+		key := count.Pack
+		if key == "" {
+			key = sticker.PackOfficial
+		}
+		pack := add(key)
+		pack.StickerCount += count.Total
+		pack.EnabledCount += count.Enabled
+	}
+	packs := make([]AdminOfficialPack, 0, len(byKey))
+	coverIDs := make([]uint64, 0, len(byKey))
+	for _, pack := range byKey {
+		packs = append(packs, *pack)
+		if pack.CoverStickerID != 0 {
+			coverIDs = append(coverIDs, pack.CoverStickerID)
+		}
+	}
+	sortPacks(packs, func(p AdminOfficialPack) (int, string) { return p.SortOrder, p.Key })
+	covers := make([]sticker.Entity, 0, len(coverIDs))
+	if len(coverIDs) > 0 {
+		if err := sticker.FindByIDs(coverIDs, &covers); err != nil {
+			return nil, err
+		}
+	}
+	for index := range packs {
+		for _, cover := range covers {
+			if cover.Id == packs[index].CoverStickerID && cover.Pack == packs[index].Key {
+				packs[index].CoverURL = ResolveURLFor(cover)
+			}
+		}
+		if packs[index].CoverURL == "" && packs[index].StickerCount > 0 {
+			var first sticker.Entity
+			err := conn.Where("is_official = ? AND pack = ? AND file_name <> ''", true, packs[index].Key).
+				Order("sort_order ASC").Order("id ASC").Limit(1).Find(&first).Error
+			if err != nil {
+				return nil, err
+			}
+			packs[index].CoverURL = ResolveURLFor(first)
+		}
+	}
+	return packs, nil
+}
+
+// knownPackTx reports whether key names a group stickers can join: a stored
+// pack, a preset, or a key that official stickers already use.
+func knownPackTx(tx *gorm.DB, key string) (bool, error) {
+	if !validPackKey(key) {
+		return false, nil
+	}
+	if _, ok := presetPackDefaults[key]; ok {
+		return true, nil
+	}
+	if _, err := sticker.OfficialPackTx(tx, key); err == nil {
+		return true, nil
+	} else if !errors.Is(err, gorm.ErrRecordNotFound) {
+		return false, err
+	}
+	var count int64
+	err := tx.Model(&sticker.Entity{}).Where("is_official = ? AND pack = ?", true, key).Count(&count).Error
+	return count > 0, err
+}
+
+// SaveOfficialPackInput creates a pack (empty Key) or edits one.
+type SaveOfficialPackInput struct {
+	Key            string `json:"key"`
+	Name           string `json:"name"`
+	SortOrder      int    `json:"sortOrder"`
+	CoverStickerID uint64 `json:"coverStickerId"`
+}
+
+// SaveOfficialPack stores a pack's name, order and cover. The cover must be
+// one of the pack's own stickers; zero picks the first one automatically.
+func SaveOfficialPack(ctx context.Context, input SaveOfficialPackInput) (string, error) {
+	name, err := cleanPackName(input.Name)
+	if err != nil {
+		return "", err
+	}
+	key := strings.TrimSpace(input.Key)
+	err = db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+		if key == "" {
+			var random [4]byte
+			if _, err := rand.Read(random[:]); err != nil {
+				return err
+			}
+			key = "p-" + hex.EncodeToString(random[:])
+		} else if known, err := knownPackTx(tx, key); err != nil {
+			return err
+		} else if !known {
+			return ErrPackInvalid
+		}
+		if input.CoverStickerID != 0 {
+			cover, err := sticker.GetByIDTx(tx, input.CoverStickerID)
+			if errors.Is(err, gorm.ErrRecordNotFound) || err == nil && (!cover.IsOfficial || cover.Pack != key) {
+				return ErrPackInvalid
+			}
+			if err != nil {
+				return err
+			}
+		}
+		return sticker.SaveOfficialPackTx(tx, &sticker.OfficialPack{Key: key, Name: name, SortOrder: input.SortOrder, CoverStickerID: input.CoverStickerID})
+	})
+	if err != nil {
+		return "", err
+	}
+	InvalidateCache()
+	return key, nil
+}
+
+// DeleteOfficialPack moves a pack's stickers into another pack and removes
+// its metadata. Stickers keep their names, so sent content is unaffected. The
+// default pack holds new uploads and cannot be removed.
+func DeleteOfficialPack(ctx context.Context, key, moveTo string) (int64, error) {
+	if moveTo == "" {
+		moveTo = sticker.PackOfficial
+	}
+	if key == sticker.PackOfficial || key == moveTo || !validPackKey(key) {
+		return 0, ErrPackInvalid
+	}
+	var moved int64
+	err := db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+		for _, candidate := range []string{key, moveTo} {
+			if known, err := knownPackTx(tx, candidate); err != nil {
+				return err
+			} else if !known {
+				return ErrPackInvalid
+			}
+		}
+		var err error
+		if moved, err = sticker.MoveOfficialStickersTx(tx, key, moveTo); err != nil {
+			return err
+		}
+		return sticker.DeleteOfficialPackTx(tx, key)
+	})
+	if err != nil {
+		return 0, err
+	}
+	InvalidateCache()
+	return moved, nil
+}
+
+// Batch actions administrators apply to selected official stickers.
+const (
+	BatchEnable  = "enable"
+	BatchDisable = "disable"
+	BatchMove    = "move"
+	BatchDelete  = "delete"
+)
+
+// BatchInput applies one action to up to MaxBatchStickers official stickers.
+// Pack is the target of BatchMove.
+type BatchInput struct {
+	IDs    []uint64 `json:"ids"`
+	Action string   `json:"action"`
+	Pack   string   `json:"pack"`
+}
+
+// BatchStickers applies the action in one transaction and returns how many
+// official stickers it changed; ids of other or missing stickers are ignored.
+func BatchStickers(ctx context.Context, input BatchInput) (int, error) {
+	ids := slices.Compact(slices.Sorted(slices.Values(input.IDs)))
+	if len(ids) > 0 && ids[0] == 0 {
+		ids = ids[1:]
+	}
+	if len(ids) == 0 || len(ids) > MaxBatchStickers {
+		return 0, ErrPackInvalid
+	}
+	switch input.Action {
+	case BatchEnable, BatchDisable, BatchMove, BatchDelete:
+	default:
+		return 0, ErrPackInvalid
+	}
+	changed := 0
+	err := db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+		if input.Action == BatchMove {
+			if known, err := knownPackTx(tx, input.Pack); err != nil {
+				return err
+			} else if !known {
+				return ErrPackInvalid
+			}
+		}
+		rows, err := sticker.OfficialByIDsTx(tx, ids)
+		if err != nil {
+			return err
+		}
+		for _, row := range rows {
+			switch input.Action {
+			case BatchEnable, BatchDisable:
+				enabled := input.Action == BatchEnable
+				if row.IsEnabled == enabled {
+					continue
+				}
+				err = tx.Model(&sticker.Entity{}).Where("id = ?", row.Id).Update("is_enabled", enabled).Error
+			case BatchMove:
+				if row.Pack == input.Pack {
+					continue
+				}
+				err = tx.Model(&sticker.Entity{}).Where("id = ?", row.Id).Update("pack", input.Pack).Error
+			case BatchDelete:
+				if err = fileusageservice.SetStickerUsageTx(tx, row.Id, 0, "", fileUsage.UsageStatusActive); err == nil {
+					err = sticker.DeleteTx(tx, row.Id)
+				}
+			}
+			if err != nil {
+				return err
+			}
+			changed++
+		}
+		return nil
+	})
+	if err != nil {
+		return 0, err
+	}
+	InvalidateCache()
+	return changed, nil
+}

