+	var savedEntry sticker.LibraryEntry
+	if err := db.Connect().Where("user_id = ? AND sticker_id = ?", entry.UserID, row.Id).First(&savedEntry).Error; err != nil || savedEntry.DisplayName != entry.DisplayName {
