+
+	first, err := svc.ApplyReward(context.Background(), AwardRequest{UserID: 7, RuleKey: DailyBaseRuleKey, SourceKey: "daily:7:2026-01-02", OccurredAt: now})
+	if err != nil {
+		t.Fatalf("daily base award: %v", err)
+	}
