+		// 时既对读者不可见，又会被孤儿回收任务当成未引用的上传删除。必须在清理任务
+		// 把它们当成孤儿之前跑完。
+		result := datamigration.BackfillFileUsagesChatCover()
+		if result.Failed > 0 {
+			return dataMigrationError("chat media and cover file usages", 37, result.Failed, result.LastFailed)
+		}
+		if err := pageConfig.SyncMigrationVersion(37); err != nil {
+			return err
+		}
+		slog.Info("app migration chat media and cover file usages backfilled", "processed", result.Processed, "inserted", result.Inserted)
+		currentVersion = 37
+	}
+	slog.Info("app migration end", "version", currentVersion, "searchIndexVersion", searchIndexVersion)
+	if searchIndexVersion < pageConfig.SearchIndexMigrationVersion {
+		// 数据迁移已跑完，但索引步骤仍在等 Meilisearch（索引是可重建投影）。
+		// 仍返回 ErrRetryLater 让 serve/独立 migrate 命令把它当作 deferred 而非失败，
+		// 并在每次启动重试。
+		slog.Warn("app migration search index steps deferred (meilisearch unavailable); run rebuild-search-index once meilisearch is configured",
+			"searchIndexVersion", searchIndexVersion, "searchIndexTargetVersion", pageConfig.SearchIndexMigrationVersion)
+		return fmt.Errorf("%w: search index steps deferred (meilisearch unavailable)", ErrRetryLater)
+	}
 	return nil
 }

 func dataMigrationError(name string, version int, failed int, lastFailed any) error {
 	slog.Error("app migration "+name+" has failures", "failed", failed, "lastFailed", lastFailed)

